import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface PodcastProject {
  id: string;
  title: string;
  description: string;
  content: string;
  audioUrl?: string;
  createdAt: number;
  duration?: string;
  voice: string;
  tone: 'formal' | 'conversational' | 'storytelling';
}

export interface VoiceOption {
  id: string;
  name: string;
  gender: 'Male' | 'Female';
  style: string;
}

export enum AppRoute {
  DASHBOARD = 'dashboard',
  STUDIO = 'studio',
  SETTINGS = 'settings'
}

// Gemini specific types usually come from the SDK, but we define internal mapped types here
export type GenerationStatus = 'idle' | 'generating_script' | 'synthesizing_audio' | 'ready' | 'error';

// Utility to convert raw PCM data to a WAV Blob for playback/download
export const pcmToWav = (
  pcmData: Float32Array | Uint8Array,
  sampleRate: number = 24000,
  numChannels: number = 1
): Blob => {
  let buffer: Float32Array;

  // Convert Uint8Array to Float32Array if necessary (assuming 16-bit input from some APIs, 
  // but Gemini usually returns raw bytes that might need decoding or are already float. 
  // Based on docs, it returns raw PCM. Let's assume we decode the base64 to standard float audio buffer first)
  // Ideally, we use AudioContext to decode, then this function writes the wav header.

  // However, constructing a WAV from an AudioBuffer is safer.
  return audioBufferToWav(pcmData as unknown as AudioBuffer); 
  // NOTE: The above signature is a placeholder. Real implementation below uses AudioBuffer.
};

export const decodeBase64Audio = async (base64String: string, audioContext: AudioContext): Promise<AudioBuffer> => {
  const binaryString = atob(base64String);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  // Raw PCM data usually doesn't have headers, so decodeAudioData might fail if it expects a container format.
  // Gemini API docs say "raw PCM". We need to manually convert PCM bytes to AudioBuffer.
  // Assuming 16-bit integer PCM, Little Endian.
  const int16Data = new Int16Array(bytes.buffer);
  const float32Data = new Float32Array(int16Data.length);

  for (let i = 0; i < int16Data.length; i++) {
    float32Data[i] = int16Data[i] / 32768.0;
  }

  const buffer = audioContext.createBuffer(1, float32Data.length, 24000); // 24kHz is standard for Gemini Flash TTS
  buffer.getChannelData(0).set(float32Data);
  return buffer;
};

export const audioBufferToWav = (buffer: AudioBuffer): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const length = buffer.length * numOfChan * 2 + 44;
  const bufferOut = new ArrayBuffer(length);
  const view = new DataView(bufferOut);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write WAVE header
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  setUint32(0x20746d66); // "fmt " chunk
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(buffer.sampleRate);
  setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this example)

  setUint32(0x61746164); // "data" - chunk
  setUint32(length - pos - 4); // chunk length

  // write interleaved data
  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  while (pos < buffer.length) {
    for (i = 0; i < numOfChan; i++) {
      // clamp
      sample = Math.max(-1, Math.min(1, channels[i][pos])); 
      // scale to 16-bit signed int
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
      view.setInt16(44 + offset, sample, true);
      offset += 2;
    }
    pos++;
  }

  return new Blob([bufferOut], { type: "audio/wav" });

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }
};

import { GoogleGenAI, Modality } from "@google/genai";
import { decodeBase64Audio, audioBufferToWav } from "./audioUtils";

const API_KEY = process.env.API_KEY || ''; // Ensure this is set in your environment
const ai = new GoogleGenAI({ apiKey: API_KEY });

// Models
const TEXT_MODEL = 'gemini-3-flash-preview';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

/**
 * Improves or generates Afrikaans script based on input.
 */
export const generateAfrikaansScript = async (
  prompt: string, 
  tone: 'formal' | 'conversational' | 'storytelling'
): Promise<string> => {
  if (!API_KEY) throw new Error("API Key missing");

  const toneInstruction = tone === 'formal' 
    ? 'Use formal, academic or news-broadcast standard Afrikaans.' 
    : tone === 'storytelling'
    ? 'Use expressive, descriptive Afrikaans suitable for a podcast story.'
    : 'Use casual, conversational Afrikaans suitable for a friendly radio host.';

  const systemInstruction = `You are an expert Afrikaans scriptwriter for podcasts and radio. 
  Your goal is to take user input (which might be rough notes, English text, or an article) 
  and convert it into a natural-sounding Afrikaans script. 
  ${toneInstruction}
  Ensure correct grammar, idiom usage, and sentence structure for oral delivery.
  Return ONLY the script text, no markdown preamble.`;

  try {
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      },
    });
    return response.text || "Kon nie teks genereer nie.";
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Synthesizes speech from text using Gemini TTS.
 */
export const synthesizeSpeech = async (
  text: string, 
  voiceName: string = 'Kore' // Default to Kore, assuming it maps well for now
): Promise<{ audioUrl: string; duration: number }> => {
  if (!API_KEY) throw new Error("API Key missing");

  try {
    const response = await ai.models.generateContent({
      model: TTS_MODEL,
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voiceName },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received from Gemini");
    }

    // Decode and convert to WAV Blob URL
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioBuffer = await decodeBase64Audio(base64Audio, audioContext);
    const wavBlob = audioBufferToWav(audioBuffer);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      audioUrl,
      duration: audioBuffer.duration
    };

  } catch (error) {
    console.error("TTS error:", error);
    throw error;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  isLoading, 
  className = '', 
  disabled,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-orange-600 text-white hover:bg-orange-700 focus:ring-orange-500",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50 focus:ring-slate-500",
    ghost: "bg-transparent text-slate-600 hover:bg-slate-100 hover:text-slate-900 focus:ring-slate-500",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-500",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-sm",
    md: "px-4 py-2 text-sm",
    lg: "px-6 py-3 text-base",
  };

  return (
    <button
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <>
          <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          Processing...
        </>
      ) : children}
    </button>
  );
};

export default Button;

import React from 'react';
import { Mic2, LayoutDashboard, Settings, LogOut, Menu, X } from 'lucide-react';
import { AppRoute } from '../types';

interface LayoutProps {
