export default Layout;

import React, { useState, useEffect, useRef } from 'react';
import { PodcastProject, GenerationStatus } from '../types';
import Button from '../components/Button';
import { Wand2, Play, Pause, Download, Save, RefreshCw, Volume2 } from 'lucide-react';
import { generateAfrikaansScript, synthesizeSpeech } from '../services/gemini';

interface StudioProps {
  initialProject?: PodcastProject | null;
  onSave: (project: PodcastProject) => void;
}

const Studio: React.FC<StudioProps> = ({ initialProject, onSave }) => {
  const [title, setTitle] = useState(initialProject?.title || 'Nuwe Episode');
  const [content, setContent] = useState(initialProject?.content || '');
  const [tone, setTone] = useState<'formal' | 'conversational' | 'storytelling'>(initialProject?.tone || 'conversational');
  const [voice, setVoice] = useState(initialProject?.voice || 'Fenrir');

  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [audioUrl, setAudioUrl] = useState<string | null>(initialProject?.audioUrl || null);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Auto-generate project ID if new
  const projectId = useRef(initialProject?.id || `proj_${Date.now()}`);

  const handleGenerateScript = async () => {
    if (!content.trim()) return;
    setStatus('generating_script');
    try {
      // Use the existing content as a prompt or rough draft
      const improvedScript = await generateAfrikaansScript(content, tone);
      setContent(improvedScript);
      setStatus('idle');
    } catch (e) {
      alert("Failed to generate script. Please check your API key.");
      setStatus('error');
    }
  };

  const handleSynthesize = async () => {
    if (!content.trim()) return;
    setStatus('synthesizing_audio');
    try {
      const result = await synthesizeSpeech(content, voice);
      setAudioUrl(result.audioUrl);
      setStatus('ready');
    } catch (e) {
      alert("Failed to synthesize audio. Please try again.");
      setStatus('error');
    }
  };

  const togglePlayback = () => {
    if (!audioRef.current || !audioUrl) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleSave = () => {
    onSave({
      id: projectId.current,
      title,
      description: content.slice(0, 100) + '...',
      content,
      audioUrl: audioUrl || undefined,
      createdAt: initialProject?.createdAt || Date.now(),
      voice,
      tone
    });
    alert("Projek gestoor!");
  };

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.onended = () => setIsPlaying(false);
    }
  }, [audioUrl]);

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col lg:flex-row gap-6">
      {/* Left Column: Script Editor */}
      <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-50">
          <input 
            type="text" 
            value={title} 
            onChange={(e) => setTitle(e.target.value)}
            className="bg-transparent border-none font-semibold text-lg text-slate-900 focus:ring-0 w-full"
            placeholder="Episode Titel..."
          />
          <div className="flex items-center gap-2">
            <select 
              value={tone}
              onChange={(e) => setTone(e.target.value as any)}
              className="text-sm border-slate-300 rounded-md shadow-sm focus:border-orange-500 focus:ring-orange-500"
            >
              <option value="conversational">Conversational</option>
              <option value="formal">Formal / News</option>
              <option value="storytelling">Storytelling</option>
            </select>
          </div>
        </div>

        <div className="flex-1 relative">
           <textarea
            className="w-full h-full p-6 resize-none focus:outline-none text-slate-700 leading-relaxed text-lg"
            placeholder="Tik jou teks hier of plak 'n artikel..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
          <div className="absolute bottom-4 right-4 flex gap-2">
            <Button 
              size="sm" 
              variant="secondary" 
              onClick={handleGenerateScript}
              isLoading={status === 'generating_script'}
              className="shadow-sm bg-white/90 backdrop-blur"
              title="Use AI to polish Afrikaans grammar and tone"
            >
              <Wand2 className="w-4 h-4 mr-2 text-purple-600" />
              AI Verfyn
            </Button>
          </div>
        </div>
      </div>

      {/* Right Column: Audio Controls & Preview */}
      <div className="lg:w-96 flex flex-col gap-6">

        {/* Voice Settings Card */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <h3 className="font-semibold text-slate-900 mb-4 flex items-center gap-2">
            <Volume2 className="w-5 h-5 text-slate-400" />
            Stem Instellings
          </h3>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Kies 'n Stem</label>
              <div className="grid grid-cols-2 gap-2">
                {['Fenrir', 'Kore', 'Puck', 'Zephyr'].map((v) => (
                  <button
                    key={v}
                    onClick={() => setVoice(v)}
                    className={`px-3 py-2 text-sm rounded-lg border text-left transition-all ${
                      voice === v 
                      ? 'border-orange-500 bg-orange-50 text-orange-700 ring-1 ring-orange-500' 
                      : 'border-slate-200 hover:border-slate-300 text-slate-600'
                    }`}
                  >
                    {v}
                  </button>
                ))}
              </div>
            </div>

            <Button 
              className="w-full" 
              onClick={handleSynthesize}
              isLoading={status === 'synthesizing_audio'}
              disabled={!content.trim()}
            >
              <RefreshCw className="w-4 h-4 mr-2" />
              Genereer Audio
            </Button>
          </div>
        </div>

        {/* Player Card */}
        <div className="bg-slate-900 rounded-xl shadow-lg p-6 text-white flex-1 flex flex-col justify-center items-center text-center relative overflow-hidden">
          {/* Decorative wave background */}
          <div className="absolute inset-0 opacity-10 flex items-center justify-center gap-1">
             {[...Array(20)].map((_, i) => (
               <div key={i} className="w-2 bg-white rounded-full animate-pulse" style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}></div>
             ))}
          </div>

          {audioUrl ? (
            <div className="z-10 w-full">
              <div className="w-16 h-16 bg-orange-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg shadow-orange-500/30 cursor-pointer hover:scale-105 transition-transform" onClick={togglePlayback}>
                {isPlaying ? <Pause className="w-8 h-8 fill-current" /> : <Play className="w-8 h-8 fill-current ml-1" />}
              </div>
              <h4 className="font-medium text-lg truncate mb-1">{title}</h4>
              <p className="text-slate-400 text-sm mb-6">{voice} • {tone}</p>

              <audio ref={audioRef} src={audioUrl} className="hidden" />

              <div className="flex gap-3 justify-center">
                <a 
                  href={audioUrl} 
                  download={`${title.replace(/\s+/g, '_').toLowerCase()}.wav`}
                  className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm font-medium transition-colors"
                >
                  <Download className="w-4 h-4" />
                  Laai Af (WAV)
                </a>
              </div>
            </div>
          ) : (
             <div className="z-10 text-slate-400">
               <div className="w-16 h-16 border-2 border-dashed border-slate-700 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Volume2 className="w-8 h-8" />
               </div>
               <p className="text-sm">Audio sal hier verskyn</p>
             </div>
          )}
        </div>

        <Button variant="secondary" className="w-full" onClick={handleSave}>
          <Save className="w-4 h-4 mr-2" />
          Stoor Projek
        </Button>

      </div>
    </div>
  );
};

export default Studio;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import Studio from './pages/Studio';
import { AppRoute, PodcastProject } from './types';

// Placeholder data
const MOCK_PROJECTS: PodcastProject[] = [
  {
    id: '1',
    title: 'Die Oggend Nuus',
    description: 'Daily news summary in formal Afrikaans.',
    content: 'Goeie more, hier is die nuus...',
    createdAt: Date.now() - 86400000,
    voice: 'Fenrir',
    tone: 'formal'
  },
  {
    id: '2',
    title: 'Spookstories van die Kaap',
    description: 'Episode 1: Die Vlieënde Hollander',
    content: 'Dit was n donker en stormagtige nag...',
    createdAt: Date.now() - 172800000,
    voice: 'Kore',
    tone: 'storytelling'
  }
];

const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<AppRoute>(AppRoute.DASHBOARD);
  const [projects, setProjects] = useState<PodcastProject[]>(MOCK_PROJECTS);
  const [editingProject, setEditingProject] = useState<PodcastProject | null>(null);

  const handleNavigate = (route: AppRoute) => {
    setCurrentRoute(route);
    if (route !== AppRoute.STUDIO) {
      setEditingProject(null);
    }
  };

  const handleEditProject = (project: PodcastProject) => {
    setEditingProject(project);
    setCurrentRoute(AppRoute.STUDIO);
  };

  const handleSaveProject = (project: PodcastProject) => {
    setProjects(prev => {
      const exists = prev.find(p => p.id === project.id);
      if (exists) {
        return prev.map(p => p.id === project.id ? project : p);
      }
      return [project, ...prev];
    });
    setEditingProject(project); // Keep editing
  };

  return (
    <Layout currentRoute={currentRoute} onNavigate={handleNavigate}>
      {currentRoute === AppRoute.DASHBOARD && (
        <Dashboard 
          onNavigate={handleNavigate} 
          projects={projects}
          onEditProject={handleEditProject}
        />
      )}

      {currentRoute === AppRoute.STUDIO && (
        <Studio 
          initialProject={editingProject} 
          onSave={handleSaveProject}
        />
      )}

      {currentRoute === AppRoute.SETTINGS && (
        <div className="max-w-2xl">
          <h1 className="text-2xl font-bold text-slate-900 mb-6">Settings</h1>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-medium mb-4">API Configuration</h2>
            <p className="text-sm text-slate-500 mb-4">
