export type GenerationStatus = 'idle' | 'generating_script' | 'synthesizing_audio' | 'mixing' | 'ready' | 'error';

// Utility to convert raw PCM data to a WAV Blob for playback/download
export const pcmToWav = (
  pcmData: Float32Array | Uint8Array,
  sampleRate: number = 24000,
  numChannels: number = 1
): Blob => {
  return audioBufferToWav(pcmData as unknown as AudioBuffer); 
};

export const decodeBase64Audio = async (base64String: string, audioContext: AudioContext): Promise<AudioBuffer> => {
  const binaryString = atob(base64String);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  const int16Data = new Int16Array(bytes.buffer);
  const float32Data = new Float32Array(int16Data.length);

  for (let i = 0; i < int16Data.length; i++) {
    float32Data[i] = int16Data[i] / 32768.0;
  }

  const buffer = audioContext.createBuffer(1, float32Data.length, 24000); // 24kHz is standard for Gemini Flash TTS
  buffer.getChannelData(0).set(float32Data);
  return buffer;
};

export const audioBufferToWav = (buffer: AudioBuffer): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const length = buffer.length * numOfChan * 2 + 44;
  const bufferOut = new ArrayBuffer(length);
  const view = new DataView(bufferOut);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  setUint32(0x20746d66); // "fmt " chunk
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(buffer.sampleRate);
  setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this example)

  setUint32(0x61746164); // "data" - chunk
  setUint32(length - pos - 4); // chunk length

  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  while (pos < buffer.length) {
    for (i = 0; i < numOfChan; i++) {
      sample = Math.max(-1, Math.min(1, channels[i][pos])); 
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
      view.setInt16(44 + offset, sample, true);
      offset += 2;
    }
    pos++;
  }

  return new Blob([bufferOut], { type: "audio/wav" });

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }
};

// --- AUDIO MIXING & GENERATION ---

// Generates a simple synthesized jingle so we don't rely on external assets
const generateJingle = (type: 'news' | 'story' | 'upbeat', ctx: BaseAudioContext): AudioBuffer => {
  const duration = 4; // seconds
  const buffer = ctx.createBuffer(2, ctx.sampleRate * duration, ctx.sampleRate);
  const left = buffer.getChannelData(0);
  const right = buffer.getChannelData(1);

  // Simple additive synthesis
  for (let i = 0; i < buffer.length; i++) {
    const t = i / ctx.sampleRate;
    let val = 0;

    if (type === 'news') {
      // Fast, rhythmic pulses
      val = Math.sin(t * 440 * 2 * Math.PI) * Math.exp(-4 * (t % 0.5)); 
      val += Math.sin(t * 880 * 2 * Math.PI) * Math.exp(-8 * (t % 0.25)) * 0.5;
    } else if (type === 'story') {
      // Slow, sweeping pad
      val = Math.sin(t * 220 * 2 * Math.PI) * 0.5;
      val += Math.sin(t * 330 * 2 * Math.PI + t) * 0.3; // Slight detune
      val *= Math.min(t, 1) * Math.min(duration - t, 1); // Fade in/out
    } else {
      // Upbeat arpeggio
      const note = Math.floor(t * 8) % 4; // Change note every 1/8th sec
      const freq = 440 * [1, 1.25, 1.5, 2][note]; // Major chord
      val = Math.sin(i / ctx.sampleRate * freq * 2 * Math.PI) * 0.3;
    }

    left[i] = val;
    right[i] = val;
  }
  return buffer;
};

export const mixPodcastAudio = async (
  voiceBuffer: AudioBuffer,
  introType: 'news' | 'story' | 'upbeat' | 'none',
  outroType: 'news' | 'story' | 'upbeat' | 'none',
  speed: number = 1.0
): Promise<AudioBuffer> => {
  // We use OfflineAudioContext to render the final mix faster than real-time
  const sampleRate = 24000;

  // Calculate roughly needed duration (will truncate later if needed, but OAC needs fixed length)
  const estimatedDuration = (voiceBuffer.duration / speed) + 10; 
  const offlineCtx = new OfflineAudioContext(2, estimatedDuration * sampleRate, sampleRate);

  // 1. Generate Jingles
  const intro = introType !== 'none' ? generateJingle(introType, offlineCtx) : null;
  const outro = outroType !== 'none' ? generateJingle(outroType, offlineCtx) : null;

  // 2. Schedule Intro
  let currentTime = 0;
  if (intro) {
    const src = offlineCtx.createBufferSource();
    src.buffer = intro;
    src.connect(offlineCtx.destination);
    src.start(0);
    // Overlap voice with end of intro by 1 second
    currentTime += Math.max(0, intro.duration - 1.5); 
  }

  // 3. Schedule Voice
  const voiceSrc = offlineCtx.createBufferSource();
  voiceSrc.buffer = voiceBuffer;
  voiceSrc.playbackRate.value = speed; // Apply speed here physically
  voiceSrc.connect(offlineCtx.destination);
  voiceSrc.start(currentTime);

  const voiceRealDuration = voiceBuffer.duration / speed;
  currentTime += voiceRealDuration;

  // 4. Schedule Outro
  if (outro) {
    // Overlap outro with end of voice by 0.5 second
    const startOutro = Math.max(0, currentTime - 1.0);
    const src = offlineCtx.createBufferSource();
    src.buffer = outro;
    src.connect(offlineCtx.destination);
    src.start(startOutro);
    currentTime = startOutro + outro.duration;
  }

  // Render
  const renderedBuffer = await offlineCtx.startRendering();

  // Trim empty space if any
  return renderedBuffer;
};

import { GoogleGenAI, Modality } from "@google/genai";
import { decodeBase64Audio, audioBufferToWav } from "./audioUtils";

const API_KEY = process.env.API_KEY || ''; // Ensure this is set in your environment
const ai = new GoogleGenAI({ apiKey: API_KEY });

// Models
const TEXT_MODEL = 'gemini-3-flash-preview';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

/**
 * Improves or generates Afrikaans script based on input.
 */
export const generateAfrikaansScript = async (
  prompt: string, 
  tone: 'formal' | 'conversational' | 'storytelling'
): Promise<string> => {
  if (!API_KEY) throw new Error("API Key missing");

  const toneInstruction = tone === 'formal' 
    ? 'Use formal, academic or news-broadcast standard Afrikaans.' 
    : tone === 'storytelling'
    ? 'Use expressive, descriptive Afrikaans suitable for a podcast story.'
    : 'Use casual, conversational Afrikaans suitable for a friendly radio host.';

  const systemInstruction = `You are an expert Afrikaans scriptwriter for podcasts and radio. 
  Your goal is to take user input (which might be rough notes, English text, or an article) 
  and convert it into a natural-sounding Afrikaans script. 
  ${toneInstruction}
  Ensure correct grammar, idiom usage, and sentence structure for oral delivery.
  You may insert [Pause] markers where appropriate for dramatic effect, but do not use other markdown.
  Return ONLY the script text.`;

  try {
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      },
    });
    return response.text || "Kon nie teks genereer nie.";
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Synthesizes speech from text using Gemini TTS.
 */
export const synthesizeSpeech = async (
  text: string, 
  voiceName: string = 'Kore'
): Promise<{ audioUrl: string; duration: number; buffer: AudioBuffer }> => {
  if (!API_KEY) throw new Error("API Key missing");

  // Remove [Pause] markers or similar for TTS if model doesn't support them natively as silence.
  // Gemini TTS usually handles punctuation well. Let's strip explicit bracket markers to avoid it reading "Bracket Pause Bracket".
  const cleanText = text.replace(/\[.*?\]/g, ' ... '); 

  try {
    const response = await ai.models.generateContent({
      model: TTS_MODEL,
      contents: [{ parts: [{ text: cleanText }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voiceName },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received from Gemini");
    }

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioBuffer = await decodeBase64Audio(base64Audio, audioContext);
    const wavBlob = audioBufferToWav(audioBuffer);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      audioUrl,
      duration: audioBuffer.duration,
      buffer: audioBuffer
    };

  } catch (error) {
    console.error("TTS error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { PodcastProject, GenerationStatus, ProductionSettings, Chapter } from '../types';
import Button from '../components/Button';
import { Wand2, Play, Pause, Download, Save, RefreshCw, Volume2, Music, Mic2, Layers, Sliders, Flag } from 'lucide-react';
import { generateAfrikaansScript, synthesizeSpeech } from '../services/gemini';
import { mixPodcastAudio, audioBufferToWav } from '../services/audioUtils';

interface StudioProps {
  initialProject?: PodcastProject | null;
  onSave: (project: PodcastProject) => void;
}

const Studio: React.FC<StudioProps> = ({ initialProject, onSave }) => {
  // Project State
  const [title, setTitle] = useState(initialProject?.title || 'Nuwe Episode');
  const [content, setContent] = useState(initialProject?.content || '');
  const [tone, setTone] = useState<'formal' | 'conversational' | 'storytelling'>(initialProject?.tone || 'conversational');
  const [voice, setVoice] = useState(initialProject?.voice || 'Fenrir');
  const [chapters, setChapters] = useState<Chapter[]>(initialProject?.chapters || []);

  // Production State
  const [prodSettings, setProdSettings] = useState<ProductionSettings>(initialProject?.productionSettings || {
    introMusic: 'none',
    outroMusic: 'none',
    playbackSpeed: 1.0,
    pitch: 0,
    musicVolume: 0.5
  });

  // System State
  const [activeTab, setActiveTab] = useState<'script' | 'production'>('script');
  const [status, setStatus] = useState<GenerationStatus>('idle');

  // Audio State
  const [audioUrl, setAudioUrl] = useState<string | null>(initialProject?.audioUrl || null);
  const [rawVoiceBuffer, setRawVoiceBuffer] = useState<AudioBuffer | null>(null); // Store raw voice for remixing
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const projectId = useRef(initialProject?.id || `proj_${Date.now()}`);

  // --- Handlers ---

  const handleGenerateScript = async () => {
    if (!content.trim()) return;
    setStatus('generating_script');
    try {
      const improvedScript = await generateAfrikaansScript(content, tone);
      setContent(improvedScript);
      setStatus('idle');
    } catch (e) {
      alert("Failed to generate script. Please check your API key.");
      setStatus('error');
    }
  };

  const handleSynthesize = async () => {
    if (!content.trim()) return;
    setStatus('synthesizing_audio');
    try {
      const result = await synthesizeSpeech(content, voice);
      setRawVoiceBuffer(result.buffer); // Save raw buffer for mixing

      // Perform initial mix (defaults)
      await performMix(result.buffer);

      setStatus('ready');
    } catch (e) {
      alert("Failed to synthesize audio.");
      setStatus('error');
    }
  };

  const performMix = async (bufferToMix: AudioBuffer | null = rawVoiceBuffer) => {
    if (!bufferToMix) return;
    setStatus('mixing');
    try {
      const mixedBuffer = await mixPodcastAudio(
        bufferToMix,
        prodSettings.introMusic || 'none',
        prodSettings.outroMusic || 'none',
        prodSettings.playbackSpeed
      );

      const wavBlob = audioBufferToWav(mixedBuffer);
      const newUrl = URL.createObjectURL(wavBlob);
      setAudioUrl(newUrl);
      setStatus('ready');
    } catch (e) {
      console.error(e);
      setStatus('error');
    }
  };

  // Debounced Mix update when settings change
  useEffect(() => {
    if (status === 'ready' && rawVoiceBuffer) {
      const timer = setTimeout(() => {
        performMix(rawVoiceBuffer);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [prodSettings.introMusic, prodSettings.outroMusic, prodSettings.playbackSpeed]);

  const togglePlayback = () => {
    if (!audioRef.current || !audioUrl) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleSave = () => {
    onSave({
      id: projectId.current,
      title,
      description: content.slice(0, 100) + '...',
      content,
      audioUrl: audioUrl || undefined,
      createdAt: initialProject?.createdAt || Date.now(),
      voice,
      tone,
      productionSettings: prodSettings,
      chapters
    });
    alert("Projek gestoor!");
  };

  const insertChapter = () => {
    // Ideally, we'd find cursor position, but for MVP we just append or use simple logic
    const name = prompt("Chapter Name:");
    if (name) {
      setContent(prev => prev + `\n\n[Chapter: ${name}]\n`);
    }
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col gap-6">

      {/* Top Bar */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200">
        <div className="flex-1 w-full sm:w-auto">
          <input 
            type="text" 
            value={title} 
            onChange={(e) => setTitle(e.target.value)}
            className="bg-transparent border-none font-bold text-xl text-slate-900 focus:ring-0 w-full placeholder-slate-400"
            placeholder="Episode Titel..."
          />
        </div>
        <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
          <button
            onClick={() => setActiveTab('script')}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-all flex items-center gap-2 ${activeTab === 'script' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
          >
            <Mic2 className="w-4 h-4" /> Script
          </button>
          <button
            onClick={() => setActiveTab('production')}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-all flex items-center gap-2 ${activeTab === 'production' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
          >
            <Sliders className="w-4 h-4" /> Production
          </button>
        </div>
        <div className="flex items-center gap-2">
           <Button variant="secondary" onClick={handleSave}>
            <Save className="w-4 h-4 mr-2" />
            Save
          </Button>
