import { GoogleGenAI, Modality } from "@google/genai";
import { decodeBase64Audio, audioBufferToWav } from "./audioUtils";

const API_KEY = process.env.API_KEY || ''; // Ensure this is set in your environment
const ai = new GoogleGenAI({ apiKey: API_KEY });

// Models
const TEXT_MODEL = 'gemini-3-flash-preview';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

/**
 * Improves or generates Afrikaans script based on input.
 */
export const generateAfrikaansScript = async (
  prompt: string, 
  tone: 'formal' | 'conversational' | 'storytelling',
  length: 'short' | 'medium' | 'long' = 'medium',
  topics: string = ''
): Promise<string> => {
  if (!API_KEY) throw new Error("API Key missing");

  const toneInstruction = tone === 'formal' 
    ? 'Use formal, academic or news-broadcast standard Afrikaans.' 
    : tone === 'storytelling'
    ? 'Use expressive, descriptive Afrikaans suitable for a podcast story.'
    : 'Use casual, conversational Afrikaans suitable for a friendly radio host.';

  const lengthInstruction = length === 'short' 
    ? 'Keep the output concise (approx. 2-3 minutes speaking time).'
    : length === 'long'
    ? 'Create a detailed, in-depth script (approx. 10+ minutes speaking time).'
    : 'Aim for a standard podcast segment length (approx. 5 minutes speaking time).';

  const topicInstruction = topics 
    ? `Ensure the script specifically covers the following key topics: ${topics}.`
    : '';

  const systemInstruction = `You are an expert Afrikaans scriptwriter for podcasts and radio. 
  Your goal is to take user input (which might be rough notes, English text, or an article) 
  and convert it into a natural-sounding Afrikaans script. 

  Style Guidelines:
  - ${toneInstruction}
  - ${lengthInstruction}
  - Ensure correct grammar, idiom usage, and sentence structure for oral delivery.

  Content Requirements:
  - ${topicInstruction}

  Formatting:
  - You may insert [Pause] markers where appropriate for dramatic effect.
  - Do not use markdown formatting like bold or italics.
  - Return ONLY the script text.`;

  try {
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      },
    });
    return response.text || "Kon nie teks genereer nie.";
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Synthesizes speech from text using Gemini TTS.
 */
export const synthesizeSpeech = async (
  text: string, 
  voiceName: string = 'Kore'
): Promise<{ audioUrl: string; duration: number; buffer: AudioBuffer }> => {
  if (!API_KEY) throw new Error("API Key missing");

  // Remove [Pause] markers or similar for TTS if model doesn't support them natively as silence.
  // Gemini TTS usually handles punctuation well. Let's strip explicit bracket markers to avoid it reading "Bracket Pause Bracket".
  const cleanText = text.replace(/\[.*?\]/g, ' ... '); 

  try {
    const response = await ai.models.generateContent({
      model: TTS_MODEL,
      contents: [{ parts: [{ text: cleanText }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voiceName },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data received from Gemini");
    }

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioBuffer = await decodeBase64Audio(base64Audio, audioContext);
    const wavBlob = audioBufferToWav(audioBuffer);
    const audioUrl = URL.createObjectURL(wavBlob);

    return {
      audioUrl,
      duration: audioBuffer.duration,
      buffer: audioBuffer
    };

  } catch (error) {
    console.error("TTS error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { PodcastProject, GenerationStatus, ProductionSettings, Chapter } from '../types';
import Button from '../components/Button';
import { Wand2, Play, Pause, Download, Save, RefreshCw, Volume2, Music, Mic2, Layers, Sliders, Flag, Sparkles, ChevronDown, ChevronUp } from 'lucide-react';
import { generateAfrikaansScript, synthesizeSpeech } from '../services/gemini';
import { mixPodcastAudio, audioBufferToWav } from '../services/audioUtils';

interface StudioProps {
  initialProject?: PodcastProject | null;
  onSave: (project: PodcastProject) => void;
}

const Studio: React.FC<StudioProps> = ({ initialProject, onSave }) => {
  // Project State
  const [title, setTitle] = useState(initialProject?.title || 'Nuwe Episode');
  const [content, setContent] = useState(initialProject?.content || '');
  const [tone, setTone] = useState<'formal' | 'conversational' | 'storytelling'>(initialProject?.tone || 'conversational');
  const [voice, setVoice] = useState(initialProject?.voice || 'Fenrir');
  const [chapters, setChapters] = useState<Chapter[]>(initialProject?.chapters || []);

  // AI Gen State
  const [scriptLength, setScriptLength] = useState<'short' | 'medium' | 'long'>('medium');
  const [scriptTopics, setScriptTopics] = useState('');
  const [showAiOptions, setShowAiOptions] = useState(false);

  // Production State
  const [prodSettings, setProdSettings] = useState<ProductionSettings>(initialProject?.productionSettings || {
    introMusic: 'none',
    outroMusic: 'none',
    playbackSpeed: 1.0,
    pitch: 0,
    musicVolume: 0.5
  });

  // System State
  const [activeTab, setActiveTab] = useState<'script' | 'production'>('script');
  const [status, setStatus] = useState<GenerationStatus>('idle');

  // Audio State
  const [audioUrl, setAudioUrl] = useState<string | null>(initialProject?.audioUrl || null);
  const [rawVoiceBuffer, setRawVoiceBuffer] = useState<AudioBuffer | null>(null); // Store raw voice for remixing
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const projectId = useRef(initialProject?.id || `proj_${Date.now()}`);

  // --- Handlers ---

  const handleGenerateScript = async () => {
    if (!content.trim()) return;
    setStatus('generating_script');
    try {
      const improvedScript = await generateAfrikaansScript(content, tone, scriptLength, scriptTopics);
      setContent(improvedScript);
      setStatus('idle');
      setShowAiOptions(false);
    } catch (e) {
      alert("Failed to generate script. Please check your API key.");
      setStatus('error');
    }
  };

  const handleSynthesize = async () => {
    if (!content.trim()) return;
    setStatus('synthesizing_audio');
    try {
      const result = await synthesizeSpeech(content, voice);
      setRawVoiceBuffer(result.buffer); // Save raw buffer for mixing

      // Perform initial mix (defaults)
      await performMix(result.buffer);

      setStatus('ready');
    } catch (e) {
      alert("Failed to synthesize audio.");
      setStatus('error');
    }
  };

  const performMix = async (bufferToMix: AudioBuffer | null = rawVoiceBuffer) => {
    if (!bufferToMix) return;
    setStatus('mixing');
    try {
      const mixedBuffer = await mixPodcastAudio(
        bufferToMix,
        prodSettings.introMusic || 'none',
        prodSettings.outroMusic || 'none',
        prodSettings.playbackSpeed,
        prodSettings.musicVolume ?? 0.5
      );

      const wavBlob = audioBufferToWav(mixedBuffer);
      const newUrl = URL.createObjectURL(wavBlob);
      setAudioUrl(newUrl);
      setStatus('ready');
    } catch (e) {
      console.error(e);
      setStatus('error');
    }
  };

  // Debounced Mix update when settings change
  useEffect(() => {
    if (status === 'ready' && rawVoiceBuffer) {
      const timer = setTimeout(() => {
        performMix(rawVoiceBuffer);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [prodSettings.introMusic, prodSettings.outroMusic, prodSettings.playbackSpeed, prodSettings.musicVolume]);

  const togglePlayback = () => {
    if (!audioRef.current || !audioUrl) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleSave = () => {
    onSave({
      id: projectId.current,
      title,
      description: content.slice(0, 100) + '...',
      content,
      audioUrl: audioUrl || undefined,
      createdAt: initialProject?.createdAt || Date.now(),
      voice,
      tone,
      productionSettings: prodSettings,
      chapters
    });
    alert("Projek gestoor!");
  };

  const insertChapter = () => {
    // Ideally, we'd find cursor position, but for MVP we just append or use simple logic
    const name = prompt("Chapter Name:");
    if (name) {
      setContent(prev => prev + `\n\n[Chapter: ${name}]\n`);
    }
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col gap-6">

      {/* Top Bar */}
