                            placeholder="e.g. rugby, weather, politics..."
                            className="w-full text-sm rounded-md border-slate-300 focus:border-purple-500 focus:ring-purple-500"
                          />
                       </div>
                       <div className="md:col-span-2 flex justify-end">
                         <Button 
