import React, { useState, useEffect, useRef } from 'react';
import { PodcastProject, GenerationStatus, ProductionSettings, Chapter, DistributionMetadata } from '../types';
import Button from '../components/Button';
import { Wand2, Play, Pause, Download, Save, RefreshCw, Volume2, Music, Mic2, Layers, Sliders, Flag, Sparkles, ChevronDown, ChevronUp, Globe, Rss, Calendar, CheckCircle, AlertCircle, Share2 } from 'lucide-react';
import { generateAfrikaansScript, synthesizeSpeech } from '../services/gemini';
import { mixPodcastAudio, audioBufferToWav } from '../services/audioUtils';
import { generateRSSFeed, downloadRSS } from '../services/rssUtils';

interface StudioProps {
  initialProject?: PodcastProject | null;
  onSave: (project: PodcastProject) => void;
}

const Studio: React.FC<StudioProps> = ({ initialProject, onSave }) => {
  // Project State
  const [title, setTitle] = useState(initialProject?.title || 'Nuwe Episode');
  const [content, setContent] = useState(initialProject?.content || '');
  const [tone, setTone] = useState<'formal' | 'conversational' | 'storytelling'>(initialProject?.tone || 'conversational');
  const [voice, setVoice] = useState(initialProject?.voice || 'Fenrir');
  const [chapters, setChapters] = useState<Chapter[]>(initialProject?.chapters || []);

  // Metadata State
  const [metadata, setMetadata] = useState<DistributionMetadata>(initialProject?.metadata || {
    author: 'My Podcast',
    genre: 'Society & Culture',
    season: 1,
    episode: 1,
    type: 'full',
    explicit: false,
    publishDate: '',
  });

  const [distStatus, setDistStatus] = useState<'draft' | 'scheduled' | 'published' | 'failed'>(initialProject?.distributionStatus || 'draft');
  const [selectedPlatforms, setSelectedPlatforms] = useState<string[]>(initialProject?.platforms || []);

  // AI Gen State
  const [scriptLength, setScriptLength] = useState<'short' | 'medium' | 'long'>('medium');
  const [scriptTopics, setScriptTopics] = useState('');
  const [showAiOptions, setShowAiOptions] = useState(false);

  // Production State
  const [prodSettings, setProdSettings] = useState<ProductionSettings>(initialProject?.productionSettings || {
    introMusic: 'none',
    outroMusic: 'none',
    playbackSpeed: 1.0,
    pitch: 0,
    musicVolume: 0.5
  });

  // System State
  const [activeTab, setActiveTab] = useState<'script' | 'production' | 'distribution'>('script');
  const [status, setStatus] = useState<GenerationStatus>('idle');

  // Audio State
  const [audioUrl, setAudioUrl] = useState<string | null>(initialProject?.audioUrl || null);
  const [rawVoiceBuffer, setRawVoiceBuffer] = useState<AudioBuffer | null>(null); // Store raw voice for remixing
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const projectId = useRef(initialProject?.id || `proj_${Date.now()}`);

  // --- Handlers ---

  const handleGenerateScript = async () => {
    if (!content.trim()) return;
    setStatus('generating_script');
    try {
      const improvedScript = await generateAfrikaansScript(content, tone, scriptLength, scriptTopics);
      setContent(improvedScript);
      setStatus('idle');
      setShowAiOptions(false);
    } catch (e) {
      alert("Failed to generate script. Please check your API key.");
      setStatus('error');
    }
  };

  const handleSynthesize = async () => {
    if (!content.trim()) return;
    setStatus('synthesizing_audio');
    try {
      const result = await synthesizeSpeech(content, voice);
      setRawVoiceBuffer(result.buffer); // Save raw buffer for mixing

      // Perform initial mix (defaults)
      await performMix(result.buffer);

      setStatus('ready');
    } catch (e) {
      alert("Failed to synthesize audio.");
      setStatus('error');
    }
  };

  const performMix = async (bufferToMix: AudioBuffer | null = rawVoiceBuffer) => {
    if (!bufferToMix) return;
    setStatus('mixing');
    try {
      const mixedBuffer = await mixPodcastAudio(
        bufferToMix,
        prodSettings.introMusic || 'none',
        prodSettings.outroMusic || 'none',
        prodSettings.playbackSpeed,
        prodSettings.musicVolume ?? 0.5
      );

      const wavBlob = audioBufferToWav(mixedBuffer);
      const newUrl = URL.createObjectURL(wavBlob);
      setAudioUrl(newUrl);
      setStatus('ready');
    } catch (e) {
      console.error(e);
      setStatus('error');
    }
  };

  // Debounced Mix update when settings change
  useEffect(() => {
    if (status === 'ready' && rawVoiceBuffer) {
      const timer = setTimeout(() => {
        performMix(rawVoiceBuffer);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [prodSettings.introMusic, prodSettings.outroMusic, prodSettings.playbackSpeed, prodSettings.musicVolume]);

  const togglePlayback = () => {
    if (!audioRef.current || !audioUrl) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleSave = () => {
    onSave({
      id: projectId.current,
      title,
      description: content.slice(0, 100) + '...',
      content,
      audioUrl: audioUrl || undefined,
      createdAt: initialProject?.createdAt || Date.now(),
      duration: rawVoiceBuffer?.duration,
      voice,
      tone,
      productionSettings: prodSettings,
      chapters,
      metadata,
      distributionStatus: distStatus,
      platforms: selectedPlatforms
    });
    alert("Projek gestoor!");
  };

  const handlePublish = async () => {
    if (!audioUrl) return alert("Please generate audio before publishing.");

    setStatus('publishing');

    // Simulate API call delay
    await new Promise(r => setTimeout(r, 2000));

    setDistStatus(metadata.publishDate ? 'scheduled' : 'published');
    setStatus('idle');

    handleSave(); // Save final state

    // Auto-generate RSS for download (since we don't have a backend to host it)
    if (window.confirm("Publishing Successful! Would you like to download your RSS feed and distribution assets now?")) {
        const fullProject = {
          id: projectId.current,
          title,
          description: content.slice(0, 100) + '...',
          content,
          createdAt: initialProject?.createdAt || Date.now(),
          duration: rawVoiceBuffer?.duration,
          voice,
          tone,
          productionSettings: prodSettings,
          chapters,
          metadata,
          distributionStatus: 'published',
        } as PodcastProject;

        const rssXml = generateRSSFeed(fullProject, 5000000); // Mock size
        downloadRSS(rssXml, 'feed.xml');
    }
  };

  const togglePlatform = (id: string) => {
    if (selectedPlatforms.includes(id)) {
      setSelectedPlatforms(prev => prev.filter(p => p !== id));
    } else {
      setSelectedPlatforms(prev => [...prev, id]);
    }
  };

  const insertChapter = () => {
    const name = prompt("Chapter Name:");
    if (name) {
      setContent(prev => prev + `\n\n[Chapter: ${name}]\n`);
    }
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col gap-6">

      {/* Top Bar */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200">
        <div className="flex-1 w-full sm:w-auto">
          <input 
            type="text" 
            value={title} 
            onChange={(e) => setTitle(e.target.value)}
            className="bg-transparent border-none font-bold text-xl text-slate-900 focus:ring-0 w-full placeholder-slate-400"
            placeholder="Episode Titel..."
          />
        </div>
        <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg overflow-x-auto">
          <button
            onClick={() => setActiveTab('script')}
            className={`px-3 py-2 text-sm font-medium rounded-md transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'script' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
          >
            <Mic2 className="w-4 h-4" /> Script
          </button>
          <button
            onClick={() => setActiveTab('production')}
            className={`px-3 py-2 text-sm font-medium rounded-md transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'production' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
          >
            <Sliders className="w-4 h-4" /> Production
          </button>
           <button
            onClick={() => setActiveTab('distribution')}
            className={`px-3 py-2 text-sm font-medium rounded-md transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === 'distribution' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-600 hover:text-slate-900'}`}
          >
            <Share2 className="w-4 h-4" /> Publish
          </button>
        </div>
        <div className="flex items-center gap-2">
           <Button variant="secondary" onClick={handleSave}>
            <Save className="w-4 h-4 mr-2" />
            Save
          </Button>
          {activeTab !== 'distribution' && (
             <Button variant="primary" onClick={() => setActiveTab(activeTab === 'script' ? 'production' : 'distribution')}>
                Next <Play className="w-3 h-3 ml-2" />
             </Button>
          )}
        </div>
      </div>

      <div className="flex-1 flex flex-col lg:flex-row gap-6 overflow-hidden">

        {/* MAIN COLUMN */}
        <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">

          {activeTab === 'script' && (
            <>
              <div className="border-b border-slate-100 flex flex-col bg-slate-50 transition-all duration-300">
                 <div className="p-3 flex items-center justify-between gap-2">
                   <div className="flex items-center gap-2 flex-wrap">
                      <select 
                        value={tone}
                        onChange={(e) => setTone(e.target.value as any)}
                        className="text-sm border-slate-300 rounded-md py-1.5 focus:border-orange-500 focus:ring-orange-500"
                      >
                        <option value="conversational">Conversational</option>
                        <option value="formal">Formal / News</option>
                        <option value="storytelling">Storytelling</option>
                      </select>
                      <select 
                        value={voice}
                        onChange={(e) => setVoice(e.target.value)}
                        className="text-sm border-slate-300 rounded-md py-1.5 focus:border-orange-500 focus:ring-orange-500"
                      >
                        <option value="Fenrir">Fenrir (M)</option>
                        <option value="Kore">Kore (F)</option>
                        <option value="Puck">Puck (M)</option>
                        <option value="Zephyr">Zephyr (F)</option>
                      </select>
                   </div>
                   <div className="flex items-center gap-2">
                      <Button size="sm" variant="ghost" onClick={insertChapter} title="Insert Chapter Marker">
                         <Flag className="w-4 h-4 mr-1" /> Chapter
                      </Button>
                      <button 
                        onClick={() => setShowAiOptions(!showAiOptions)}
                        className={`text-sm font-medium px-3 py-1.5 rounded-lg flex items-center gap-2 transition-colors ${showAiOptions ? 'bg-purple-100 text-purple-700' : 'text-slate-600 hover:bg-slate-200'}`}
                      >
                        <Sparkles className="w-4 h-4" />
                        AI Tools
                        {showAiOptions ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                      </button>
                   </div>
                 </div>

                 {/* Collapsible AI Options Panel */}
                 {showAiOptions && (
                    <div className="p-4 bg-purple-50/50 border-t border-slate-100 grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-2">
                       <div className="space-y-2">
                          <label className="text-xs font-semibold text-slate-600 uppercase tracking-wider">Target Length</label>
                          <div className="flex gap-2">
                            {(['short', 'medium', 'long'] as const).map(l => (
                              <button
                                key={l}
                                onClick={() => setScriptLength(l)}
                                className={`flex-1 py-1.5 px-3 rounded text-sm capitalize border ${scriptLength === l ? 'bg-white border-purple-500 text-purple-700 shadow-sm' : 'bg-transparent border-slate-300 text-slate-600 hover:border-slate-400'}`}
                              >
                                {l}
                              </button>
                            ))}
                          </div>
                       </div>
                       <div className="space-y-2">
                          <label className="text-xs font-semibold text-slate-600 uppercase tracking-wider">Focus Topics</label>
                          <input 
                            type="text"
                            value={scriptTopics}
                            onChange={(e) => setScriptTopics(e.target.value)}
                            placeholder="e.g. rugby, weather, politics..."
                            className="w-full text-sm rounded-md border-slate-300 focus:border-purple-500 focus:ring-purple-500"
                          />
                       </div>
                       <div className="md:col-span-2 flex justify-end">
                         <Button 
                            size="sm" 
                            onClick={handleGenerateScript}
                            isLoading={status === 'generating_script'}
                            className="bg-purple-600 hover:bg-purple-700 text-white"
                          >
                            <Wand2 className="w-4 h-4 mr-2" />
                            Generate / Polish Script
                          </Button>
                       </div>
                    </div>
                 )}
              </div>
              <textarea
                className="flex-1 w-full p-6 resize-none focus:outline-none text-slate-700 leading-relaxed text-lg font-serif"
                placeholder="Write your podcast script here in Afrikaans, or paste an article..."
                value={content}
                onChange={(e) => setContent(e.target.value)}
              />
            </>
          )}

          {activeTab === 'production' && (
             <div className="p-8 space-y-8 overflow-y-auto">
                <div>
                   <h3 className="text-lg font-semibold text-slate-900 mb-4 flex items-center gap-2">
                     <Music className="w-5 h-5 text-orange-600" /> Audio Mixing
                   </h3>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-3">
                        <label className="text-sm font-medium text-slate-700">Intro Music</label>
                        <div className="grid grid-cols-2 gap-2">
                           {['none', 'news', 'story', 'upbeat'].map(t => (
                             <button
                               key={t}
                               onClick={() => setProdSettings(s => ({...s, introMusic: t as any}))}
                               className={`px-3 py-2 text-sm rounded border capitalize ${prodSettings.introMusic === t ? 'bg-orange-50 border-orange-500 text-orange-700' : 'bg-white border-slate-200 text-slate-600'}`}
                             >
                               {t}
                             </button>
                           ))}
                        </div>
                      </div>
                      <div className="space-y-3">
                        <label className="text-sm font-medium text-slate-700">Outro Music</label>
                        <div className="grid grid-cols-2 gap-2">
                           {['none', 'news', 'story', 'upbeat'].map(t => (
                             <button
                               key={t}
                               onClick={() => setProdSettings(s => ({...s, outroMusic: t as any}))}
                               className={`px-3 py-2 text-sm rounded border capitalize ${prodSettings.outroMusic === t ? 'bg-orange-50 border-orange-500 text-orange-700' : 'bg-white border-slate-200 text-slate-600'}`}
                             >
                               {t}
                             </button>
                           ))}
                        </div>
                      </div>
                   </div>

                   <div className="mt-6">
                      <label className="text-sm font-medium text-slate-700 flex justify-between">
                         Music Volume
                         <span>{Math.round((prodSettings.musicVolume || 0.5) * 100)}%</span>
                      </label>
                      <input 
                         type="range" 
                         min="0.1" 
                         max="1.0" 
                         step="0.1"
                         value={prodSettings.musicVolume || 0.5}
                         onChange={(e) => setProdSettings(s => ({...s, musicVolume: parseFloat(e.target.value)}))}
                         className="w-full mt-2 accent-orange-600"
                      />
                   </div>
                </div>

                <div className="border-t border-slate-100 pt-8">
                   <h3 className="text-lg font-semibold text-slate-900 mb-4 flex items-center gap-2">
                     <Sliders className="w-5 h-5 text-orange-600" /> Playback Control
                   </h3>
                   <div className="max-w-md space-y-6">
                      <div className="space-y-2">
                         <div className="flex justify-between">
                            <label className="text-sm font-medium text-slate-700">Speed ({prodSettings.playbackSpeed}x)</label>
                         </div>
                         <input 
                           type="range" 
                           min="0.5" 
                           max="1.5" 
                           step="0.1"
                           value={prodSettings.playbackSpeed}
                           onChange={(e) => setProdSettings(s => ({...s, playbackSpeed: parseFloat(e.target.value)}))}
                           className="w-full accent-orange-600"
                         />
                         <p className="text-xs text-slate-500">Note: Changing speed requires re-rendering the mix.</p>
                      </div>
                   </div>
                </div>

                {status === 'mixing' && (
                  <div className="text-center py-8 text-orange-600 animate-pulse">
                     Rendering Audio Mix...
                  </div>
                )}
             </div>
          )}

          {activeTab === 'distribution' && (
             <div className="p-8 space-y-8 overflow-y-auto">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   {/* Left Col: Metadata */}
                   <div className="space-y-6">
                      <h3 className="text-lg font-semibold text-slate-900 flex items-center gap-2">
                        <Rss className="w-5 h-5 text-orange-600" /> Episode Metadata
                      </h3>

                      <div className="space-y-4">
                         <div>
                            <label className="block text-sm font-medium text-slate-700">Author / Host</label>
                            <input 
                              type="text" 
                              value={metadata.author}
                              onChange={e => setMetadata({...metadata, author: e.target.value})}
                              className="mt-1 w-full rounded-md border-slate-300 shadow-sm focus:border-orange-500 focus:ring-orange-500"
                            />
                         </div>

                         <div className="grid grid-cols-2 gap-4">
                            <div>
                               <label className="block text-sm font-medium text-slate-700">Season</label>
                               <input 
                                  type="number" 
                                  value={metadata.season}
                                  onChange={e => setMetadata({...metadata, season: parseInt(e.target.value)})}
                                  className="mt-1 w-full rounded-md border-slate-300 shadow-sm focus:border-orange-500 focus:ring-orange-500"
                               />
                            </div>
                            <div>
                               <label className="block text-sm font-medium text-slate-700">Episode</label>
                               <input 
                                  type="number" 
                                  value={metadata.episode}
                                  onChange={e => setMetadata({...metadata, episode: parseInt(e.target.value)})}
                                  className="mt-1 w-full rounded-md border-slate-300 shadow-sm focus:border-orange-500 focus:ring-orange-500"
                               />
                            </div>
                         </div>

                         <div>
                            <label className="block text-sm font-medium text-slate-700">Episode Type</label>
                            <select
                               value={metadata.type}
                               onChange={e => setMetadata({...metadata, type: e.target.value as any})}
                               className="mt-1 w-full rounded-md border-slate-300 shadow-sm focus:border-orange-500 focus:ring-orange-500"
                            >
                               <option value="full">Full Episode</option>
                               <option value="trailer">Trailer</option>
                               <option value="bonus">Bonus</option>
                            </select>
                         </div>

                         <div className="flex items-center gap-2 pt-2">
                            <input 
                               type="checkbox" 
                               id="explicit"
                               checked={metadata.explicit}
                               onChange={e => setMetadata({...metadata, explicit: e.target.checked})}
                               className="rounded border-slate-300 text-orange-600 focus:ring-orange-500"
                            />
                            <label htmlFor="explicit" className="text-sm text-slate-700">Contains Explicit Content</label>
                         </div>
                      </div>
                   </div>

                   {/* Right Col: Distribution & Scheduling */}
                   <div className="space-y-6">
                      <h3 className="text-lg font-semibold text-slate-900 flex items-center gap-2">
                        <Globe className="w-5 h-5 text-orange-600" /> Distribution Channels
                      </h3>

                      <div className="space-y-3">
                         <div 
                           onClick={() => togglePlatform('spotify')}
                           className={`p-3 rounded-lg border flex items-center gap-3 cursor-pointer transition-colors ${selectedPlatforms.includes('spotify') ? 'border-green-500 bg-green-50' : 'border-slate-200 hover:bg-slate-50'}`}
                         >
                            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${selectedPlatforms.includes('spotify') ? 'bg-green-500 border-green-500' : 'border-slate-300'}`}>
                               {selectedPlatforms.includes('spotify') && <CheckCircle className="w-3 h-3 text-white" />}
                            </div>
                            <span className="font-medium text-slate-900">Spotify</span>
                         </div>

                         <div 
                           onClick={() => togglePlatform('apple')}
                           className={`p-3 rounded-lg border flex items-center gap-3 cursor-pointer transition-colors ${selectedPlatforms.includes('apple') ? 'border-purple-500 bg-purple-50' : 'border-slate-200 hover:bg-slate-50'}`}
                         >
                            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${selectedPlatforms.includes('apple') ? 'bg-purple-500 border-purple-500' : 'border-slate-300'}`}>
                               {selectedPlatforms.includes('apple') && <CheckCircle className="w-3 h-3 text-white" />}
                            </div>
                            <span className="font-medium text-slate-900">Apple Podcasts</span>
                         </div>

                         <div 
                           onClick={() => togglePlatform('rss')}
                           className={`p-3 rounded-lg border flex items-center gap-3 cursor-pointer transition-colors ${selectedPlatforms.includes('rss') ? 'border-orange-500 bg-orange-50' : 'border-slate-200 hover:bg-slate-50'}`}
                         >
                            <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${selectedPlatforms.includes('rss') ? 'bg-orange-500 border-orange-500' : 'border-slate-300'}`}>
                               {selectedPlatforms.includes('rss') && <CheckCircle className="w-3 h-3 text-white" />}
                            </div>
                            <span className="font-medium text-slate-900">Direct RSS Feed</span>
                         </div>
                      </div>

                      <div className="pt-4 border-t border-slate-100">
                         <h4 className="text-sm font-medium text-slate-700 mb-2">Schedule Publishing</h4>
                         <div className="flex gap-2">
                             <input 
                               type="datetime-local" 
                               value={metadata.publishDate}
                               onChange={e => setMetadata({...metadata, publishDate: e.target.value})}
                               className="w-full text-sm rounded-md border-slate-300 focus:border-orange-500 focus:ring-orange-500"
                             />
                         </div>
                         <p className="text-xs text-slate-500 mt-2">
                            {metadata.publishDate ? 'Episode will be released automatically at this time.' : 'Episode will be published immediately.'}
                         </p>
                      </div>
                   </div>
                </div>

                {/* Publish Action Area */}
                <div className="mt-8 pt-8 border-t border-slate-200 flex flex-col items-center justify-center text-center">
                   {distStatus === 'published' ? (
                      <div className="bg-green-50 border border-green-200 rounded-xl p-6 w-full max-w-lg">
                         <div className="mx-auto w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-3">
                            <CheckCircle className="w-6 h-6" />
                         </div>
                         <h3 className="text-xl font-bold text-green-800">Published Successfully!</h3>
                         <p className="text-green-700 mt-1 mb-4">Your episode is now live on selected platforms.</p>
                         <Button variant="secondary" onClick={() => setDistStatus('draft')}>Publish Update</Button>
                      </div>
                   ) : distStatus === 'scheduled' ? (
                       <div className="bg-blue-50 border border-blue-200 rounded-xl p-6 w-full max-w-lg">
                         <div className="mx-auto w-12 h-12 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-3">
                            <Calendar className="w-6 h-6" />
                         </div>
                         <h3 className="text-xl font-bold text-blue-800">Scheduled for Release</h3>
                         <p className="text-blue-700 mt-1 mb-4">Scheduled for: {new Date(metadata.publishDate || '').toLocaleString()}</p>
                         <Button variant="secondary" onClick={() => setDistStatus('draft')}>Cancel Schedule</Button>
                      </div>
                   ) : (
                     <div className="w-full max-w-lg space-y-4">
                        {!audioUrl && (
                           <div className="flex items-center gap-2 text-amber-600 bg-amber-50 p-3 rounded-lg text-sm mb-2">
                              <AlertCircle className="w-4 h-4" />
                              Audio must be generated before publishing.
                           </div>
                        )}
                        <Button 
                           size="lg" 
                           className="w-full text-lg py-4 shadow-lg shadow-orange-900/10"
                           disabled={!audioUrl || selectedPlatforms.length === 0}
                           isLoading={status === 'publishing'}
                           onClick={handlePublish}
                        >
                           {status === 'publishing' ? 'Distributing...' : 'Publish Episode Now'}
                        </Button>
                        <p className="text-xs text-slate-400">
                           By publishing, you confirm that you own all rights to the content.
                        </p>
                     </div>
                   )}
                </div>
             </div>
          )}
        </div>

        {/* RIGHT COLUMN: PREVIEW & EXPORT */}
        <div className="lg:w-80 flex flex-col gap-6">
           <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col h-full">
              <h3 className="font-semibold text-slate-900 mb-6">Final Output</h3>

              <div className="flex-1 bg-slate-900 rounded-xl p-6 relative flex flex-col items-center justify-center text-center text-white mb-6 overflow-hidden">
                  <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-950"></div>
                  {/* Visualizer bars */}
                  <div className="absolute bottom-0 left-0 right-0 h-16 flex items-end justify-center gap-1 opacity-20 px-4">
                     {[...Array(12)].map((_, i) => (
                       <div key={i} className={`w-full bg-orange-500 rounded-t-sm transition-all duration-300 ${isPlaying ? 'animate-pulse' : ''}`} style={{ height: `${Math.random() * 80 + 20}%` }}></div>
                     ))}
                  </div>

                  <div className="z-10 relative">
                    {audioUrl ? (
                      <>
                        <button 
                          onClick={togglePlayback}
                          className="w-16 h-16 bg-orange-500 hover:bg-orange-600 rounded-full flex items-center justify-center mb-4 transition-transform hover:scale-105 shadow-xl shadow-orange-900/50"
                        >
                          {isPlaying ? <Pause className="w-8 h-8 fill-current" /> : <Play className="w-8 h-8 fill-current ml-1" />}
                        </button>
                        <div className="text-sm font-medium text-slate-300">
                          {Math.floor((audioRef.current?.duration || 0) / 60)}:
                          {Math.floor((audioRef.current?.duration || 0) % 60).toString().padStart(2, '0')}
                        </div>
                      </>
                    ) : (
                      <div className="text-slate-500 text-sm">
                        No audio generated yet
                      </div>
                    )}
                  </div>

                  <audio 
                    ref={audioRef} 
                    src={audioUrl || undefined} 
                    onEnded={() => setIsPlaying(false)}
                    onTimeUpdate={() => { /* Force re-render for time if needed */ }}
                  />
              </div>

              <div className="space-y-3">
                 {!rawVoiceBuffer ? (
                   <Button 
                     className="w-full" 
                     onClick={handleSynthesize} 
                     isLoading={status === 'synthesizing_audio'}
                     disabled={!content.trim()}
                   >
                     <RefreshCw className="w-4 h-4 mr-2" />
                     Generate Audio
                   </Button>
                 ) : (
                   <Button 
                      className="w-full" 
                      onClick={handleSynthesize} // Re-generate
                      variant="secondary"
                      isLoading={status === 'synthesizing_audio'}
                    >
                      <RefreshCw className="w-4 h-4 mr-2" />
                      Re-Generate Voice
                    </Button>
                 )}

                 <a 
                   href={audioUrl || '#'} 
                   download={`${title.replace(/\s+/g, '_')}.wav`}
                   className={`flex items-center justify-center w-full px-4 py-2 rounded-lg font-medium transition-colors ${!audioUrl ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-slate-800 text-white hover:bg-slate-900'}`}
                   onClick={(e) => !audioUrl && e.preventDefault()}
                 >
                   <Download className="w-4 h-4 mr-2" />
                   Export WAV
                 </a>
                 <p className="text-xs text-center text-slate-400">High Quality 24kHz WAV</p>
              </div>
           </div>
        </div>

      </div>
    </div>
  );
};

export default Studio;

export interface Chapter {
  id: string;
  title: string;
  timestamp: number; // Seconds from start of voice track
}

export interface ProductionSettings {
  introMusic?: 'news' | 'story' | 'upbeat' | 'none';
  outroMusic?: 'news' | 'story' | 'upbeat' | 'none';
  playbackSpeed: number; // 0.5 to 2.0
  pitch: number; // -12 to 12 semitones (simulated via rate or detune)
  musicVolume?: number;
}

export interface DistributionMetadata {
  author: string;
  genre: string;
  season: number;
  episode: number;
  type: 'full' | 'trailer' | 'bonus';
  explicit: boolean;
  coverArt?: string; // Data URL or URL
  publishDate?: string; // ISO String for scheduling
}

export interface PodcastProject {
  id: string;
  title: string;
  description: string;
  content: string;
  audioUrl?: string;
  createdAt: number;
  duration?: number; // in seconds
  voice: string;
  tone: 'formal' | 'conversational' | 'storytelling';
  productionSettings: ProductionSettings;
  chapters: Chapter[];
  // New Distribution Fields
  metadata: DistributionMetadata;
  distributionStatus: 'draft' | 'scheduled' | 'published' | 'failed';
  platforms?: string[]; // List of IDs like 'spotify', 'apple'
}

export interface CreatorProfile {
  name: string;
  slug: string;
  bio: string;
  coverImage?: string;
  brandColor: string; // Hex
  links: {
    spotify?: string;
    apple?: string;
    rss?: string;
    website?: string;
  };
}

export interface VoiceOption {
  id: string;
  name: string;
  gender: 'Male' | 'Female';
  style: string;
}

export enum AppRoute {
  DASHBOARD = 'dashboard',
  STUDIO = 'studio',
  SETTINGS = 'settings',
  CREATOR_SETTINGS = 'creator_settings',
  PUBLIC_PAGE = 'public_page'
}

// Gemini specific types usually come from the SDK, but we define internal mapped types here
export type GenerationStatus = 'idle' | 'generating_script' | 'synthesizing_audio' | 'mixing' | 'ready' | 'error' | 'publishing';

import React from 'react';
import { Mic2, LayoutDashboard, Settings, LogOut, Menu, X, Globe } from 'lucide-react';
import { AppRoute } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  currentRoute: AppRoute;
  onNavigate: (route: AppRoute) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, currentRoute, onNavigate }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);

  // If we are on the public page, render a simplified layout
  if (currentRoute === AppRoute.PUBLIC_PAGE) {
    return (
      <div className="min-h-screen bg-white">
        {children}
      </div>
    );
  }

  const navItems = [
    { id: AppRoute.DASHBOARD, label: 'Dashboard', icon: LayoutDashboard },
    { id: AppRoute.STUDIO, label: 'Studio', icon: Mic2 },
    { id: AppRoute.CREATOR_SETTINGS, label: 'Creator Page', icon: Globe },
    { id: AppRoute.SETTINGS, label: 'Settings', icon: Settings },
  ];

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 overflow-hidden">
      {/* Sidebar for Desktop */}
      <aside className="hidden md:flex flex-col w-64 bg-white border-r border-slate-200">
        <div className="p-6 flex items-center gap-2 border-b border-slate-100">
          <div className="w-8 h-8 bg-orange-600 rounded-lg flex items-center justify-center text-white font-bold text-lg">
            S
          </div>
          <span className="text-xl font-bold tracking-tight text-slate-800">StemGolf</span>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 text-sm font-medium rounded-lg transition-colors ${
                currentRoute === item.id 
                  ? 'bg-orange-50 text-orange-700' 
                  : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
              }`}
            >
              <item.icon className={`w-5 h-5 ${currentRoute === item.id ? 'text-orange-600' : 'text-slate-400'}`} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <div className="flex items-center gap-3 px-4 py-2">
            <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-xs font-medium text-slate-600">
              JD
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-slate-900 truncate">Jan De Vries</p>
              <p className="text-xs text-slate-500 truncate">Pro Plan</p>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full bg-white border-b border-slate-200 z-20 flex items-center justify-between p-4">
        <div className="flex items-center gap-2">
           <div className="w-8 h-8 bg-orange-600 rounded-lg flex items-center justify-center text-white font-bold text-lg">
            S
          </div>
          <span className="text-lg font-bold text-slate-800">StemGolf</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="text-slate-600">
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 bg-white z-10 pt-20 px-4">
           <nav className="space-y-2">
            {navItems.map((item) => (
              <button
