import React, { useState } from 'react';
import { CreatorProfile, PodcastProject, AppRoute } from '../types';
import { Play, Pause, Share2, ArrowLeft, Headphones } from 'lucide-react';

interface PublicPageProps {
  profile: CreatorProfile;
  projects: PodcastProject[];
  onNavigate: (route: AppRoute) => void;
}

const PublicPage: React.FC<PublicPageProps> = ({ profile, projects, onNavigate }) => {
  // Only show published episodes
  const publishedEpisodes = projects.filter(p => p.distributionStatus === 'published' || p.distributionStatus === 'scheduled');

  const [playingId, setPlayingId] = useState<string | null>(null);
  const [audioEl, setAudioEl] = useState<HTMLAudioElement | null>(null);

  const togglePlay = (project: PodcastProject) => {
    if (!project.audioUrl) return;

    if (playingId === project.id && audioEl) {
      if (audioEl.paused) {
        audioEl.play();
      } else {
        audioEl.pause();
        setPlayingId(null);
      }
    } else {
      if (audioEl) {
        audioEl.pause();
      }
      const newAudio = new Audio(project.audioUrl);
      newAudio.play();
      newAudio.onended = () => setPlayingId(null);
      setAudioEl(newAudio);
      setPlayingId(project.id);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-12 relative">
      {/* Floating Back Button for Demo */}
      <button 
        onClick={() => onNavigate(AppRoute.CREATOR_SETTINGS)}
        className="fixed top-4 left-4 z-50 bg-white/80 backdrop-blur p-2 rounded-full shadow-md text-slate-600 hover:text-slate-900"
      >
        <ArrowLeft className="w-5 h-5" />
      </button>

      {/* Hero Section */}
      <div 
        className="relative pt-20 pb-16 px-4 text-center overflow-hidden"
        style={{ backgroundColor: profile.brandColor }}
      >
        {/* Abstract Background Shapes */}
        <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
           <div className="absolute -top-10 -left-10 w-64 h-64 rounded-full bg-white mix-blend-overlay blur-3xl"></div>
           <div className="absolute top-1/2 right-0 w-48 h-48 rounded-full bg-black mix-blend-overlay blur-3xl"></div>
        </div>

        <div className="relative z-10 max-w-md mx-auto">
          <div className="w-32 h-32 mx-auto bg-white rounded-2xl shadow-xl mb-6 overflow-hidden flex items-center justify-center">
             {profile.coverImage ? (
                <img src={profile.coverImage} alt="Cover" className="w-full h-full object-cover" />
             ) : (
                <span className="text-4xl font-bold" style={{color: profile.brandColor}}>
                  {profile.name.charAt(0)}
                </span>
             )}
          </div>
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">{profile.name}</h1>
          <p className="text-white/90 text-lg leading-relaxed">{profile.bio}</p>

          {/* Social Links */}
          <div className="flex items-center justify-center gap-3 mt-6">
            {profile.links.spotify && (
               <a href={profile.links.spotify} target="_blank" rel="noopener noreferrer" className="bg-white/20 hover:bg-white/30 backdrop-blur text-white px-4 py-2 rounded-full text-sm font-medium transition-colors">
                  Spotify
               </a>
            )}
            {profile.links.apple && (
               <a href={profile.links.apple} target="_blank" rel="noopener noreferrer" className="bg-white/20 hover:bg-white/30 backdrop-blur text-white px-4 py-2 rounded-full text-sm font-medium transition-colors">
                  Apple
               </a>
            )}
             {profile.links.website && (
               <a href={profile.links.website} target="_blank" rel="noopener noreferrer" className="bg-white/20 hover:bg-white/30 backdrop-blur text-white px-4 py-2 rounded-full text-sm font-medium transition-colors">
                  Website
               </a>
            )}
          </div>
        </div>
      </div>

      {/* Episodes List */}
      <div className="max-w-xl mx-auto px-4 -mt-6 relative z-20">
        <div className="bg-white rounded-xl shadow-lg border border-slate-100 divide-y divide-slate-100 overflow-hidden">
           <div className="p-4 bg-slate-50 border-b border-slate-100">
              <h2 className="font-semibold text-slate-700 uppercase tracking-wider text-xs">Latest Episodes</h2>
           </div>

           {publishedEpisodes.length === 0 ? (
             <div className="p-8 text-center text-slate-500">
                <Headphones className="w-12 h-12 mx-auto text-slate-300 mb-3" />
                <p>No episodes published yet.</p>
             </div>
           ) : (
             publishedEpisodes.map(ep => (
               <div key={ep.id} className="p-4 hover:bg-slate-50 transition-colors">
                  <div className="flex gap-4">
                     <button 
                       onClick={() => togglePlay(ep)}
                       className="flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all hover:scale-105"
                       style={{ 
                         backgroundColor: playingId === ep.id ? '#1e293b' : profile.brandColor,
                         color: 'white'
                       }}
                     >
                        {playingId === ep.id ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5 ml-1" />}
                     </button>
                     <div className="flex-1 min-w-0">
                        <h3 className="font-semibold text-slate-900 leading-tight">{ep.title}</h3>
                        <div className="flex items-center gap-2 text-xs text-slate-500 mt-1">
                           <span>{new Date(ep.createdAt).toLocaleDateString()}</span>
                           <span>•</span>
                           <span>{Math.floor((ep.duration || 0) / 60)} min</span>
                        </div>
                        <p className="text-sm text-slate-600 mt-2 line-clamp-2">{ep.description}</p>
                     </div>
                  </div>
               </div>
             ))
           )}
        </div>

        <div className="mt-8 text-center">
           <p className="text-xs text-slate-400">
             Powered by <span className="font-semibold text-slate-600">StemGolf</span>
           </p>
        </div>
      </div>
    </div>
  );
};

