                       <div className="bg-blue-50 border border-blue-200 rounded-xl p-6 w-full max-w-lg">
                         <div className="mx-auto w-12 h-12 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-3">
                            <Calendar className="w-6 h-6" />
                         </div>
                         <h3 className="text-xl font-bold text-blue-800">Scheduled for Release</h3>
                         <p className="text-blue-700 mt-1 mb-4">Scheduled for: {new Date(metadata.publishDate || '').toLocaleString()}</p>
                         <Button variant="secondary" onClick={() => setDistStatus('draft')}>Cancel Schedule</Button>
                      </div>
                   ) : (
                     <div className="w-full max-w-lg space-y-4">
                        {!audioUrl && (
                           <div className="flex items-center gap-2 text-amber-600 bg-amber-50 p-3 rounded-lg text-sm mb-2">
                              <AlertCircle className="w-4 h-4" />
