      explicit: true,
    },
    distributionStatus: 'published'
  }
];

const DEFAULT_PROFILE: CreatorProfile = {
  name: 'Jan De Vries',
  slug: 'jan-se-nuus',
  bio: 'Bringing you the latest updates and stories from Cape Town in authentic Afrikaans.',
  brandColor: '#ea580c',
  links: {
    spotify: 'https://spotify.com',
    website: 'https://stemgolf.app'
  },
  theme: 'classic',
  font: 'modern',
  removeBranding: false
};

const STORAGE_KEY = 'stemgolf_projects_data';
const PROFILE_KEY = 'stemgolf_creator_profile';

const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<AppRoute>(AppRoute.DASHBOARD);

  // Initialize projects
  const [projects, setProjects] = useState<PodcastProject[]>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return JSON.parse(savedData);
      }
      return MOCK_PROJECTS;
    } catch (e) {
      console.error("Failed to load projects", e);
      return MOCK_PROJECTS;
    }
  });

  // Initialize profile
  const [profile, setProfile] = useState<CreatorProfile>(() => {
     try {
      const savedData = localStorage.getItem(PROFILE_KEY);
      if (savedData) {
        return { ...DEFAULT_PROFILE, ...JSON.parse(savedData) }; // Merge to ensure new fields exist
      }
      return DEFAULT_PROFILE;
    } catch (e) {
      return DEFAULT_PROFILE;
    }
  });

  const [editingProject, setEditingProject] = useState<PodcastProject | null>(null);

  // Persist projects
  useEffect(() => {
    try {
      const projectsToSave = projects.map(p => {
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        const { audioUrl, ...rest } = p; 
        return rest;
      });
      localStorage.setItem(STORAGE_KEY, JSON.stringify(projectsToSave));
    } catch (e) {
      console.error("Failed to save projects", e);
    }
  }, [projects]);

  // Persist profile
  useEffect(() => {
    try {
      localStorage.setItem(PROFILE_KEY, JSON.stringify(profile));
    } catch (e) {
      console.error("Failed to save profile", e);
    }
  }, [profile]);

  const handleNavigate = (route: AppRoute) => {
    setCurrentRoute(route);
    if (route !== AppRoute.STUDIO) {
      setEditingProject(null);
    }
  };

  const handleEditProject = (project: PodcastProject) => {
    setEditingProject(project);
    setCurrentRoute(AppRoute.STUDIO);
  };

  const handleSaveProject = (project: PodcastProject) => {
    setProjects(prev => {
      const exists = prev.find(p => p.id === project.id);
      if (exists) {
        return prev.map(p => p.id === project.id ? project : p);
      }
      return [project, ...prev];
    });
    setEditingProject(project); 
  };

  const handleDeleteProject = (projectId: string) => {
    if (window.confirm("Are you sure you want to delete this project? This cannot be undone.")) {
      setProjects(prev => prev.filter(p => p.id !== projectId));
      if (editingProject?.id === projectId) {
        setEditingProject(null); // Switch to new project mode if current is deleted
      }
    }
  };

  const handleDuplicateProject = (project: PodcastProject) => {
    const newProject: PodcastProject = {
      ...project,
      id: `proj_${Date.now()}`,
      title: `${project.title} (Copy)`,
      createdAt: Date.now(),
      distributionStatus: 'draft',
      audioUrl: undefined // Audio URL is likely ephemeral or blob, don't copy
    };
    setProjects(prev => [newProject, ...prev]);
  };

  const handleUpdateProfile = (newProfile: CreatorProfile) => {
    setProfile(newProfile);
  };

  return (
    <Layout currentRoute={currentRoute} onNavigate={handleNavigate}>
      {currentRoute === AppRoute.DASHBOARD && (
        <Dashboard 
          onNavigate={handleNavigate} 
          projects={projects}
          onEditProject={handleEditProject}
        />
      )}

      {currentRoute === AppRoute.STUDIO && (
        <Studio 
          initialProject={editingProject} 
          projects={projects}
          onSave={handleSaveProject}
          onSelectProject={setEditingProject}
          onDeleteProject={handleDeleteProject}
          onDuplicateProject={handleDuplicateProject}
        />
      )}

      {currentRoute === AppRoute.ANALYTICS && (
        <Analytics />
      )}

      {currentRoute === AppRoute.CREATOR_SETTINGS && (
        <CreatorSettings 
          profile={profile}
          onUpdate={handleUpdateProfile}
          onNavigate={handleNavigate}
        />
      )}

      {currentRoute === AppRoute.PUBLIC_PAGE && (
        <PublicPage 
          profile={profile}
          projects={projects}
          onNavigate={handleNavigate}
        />
      )}

      {currentRoute === AppRoute.SETTINGS && (
        <div className="max-w-2xl">
          <h1 className="text-2xl font-bold text-slate-900 mb-6">Settings</h1>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-medium mb-4">API Configuration</h2>
            <p className="text-sm text-slate-500 mb-4">
              This application uses the Google Gemini API. Ensure your API key is configured in the environment variables (process.env.API_KEY).
            </p>
            <div className="p-4 bg-slate-50 rounded-lg border border-slate-200 text-sm font-mono text-slate-600 break-all">
              {process.env.API_KEY ? 'API Key is configured ✅' : 'Warning: API_KEY is missing from environment.'}
            </div>
          </div>

          <div className="mt-8 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-medium mb-4">Storage Management</h2>
            <p className="text-sm text-slate-500 mb-4">
              Your projects are saved locally in your browser.
            </p>
            <button 
              onClick={() => {
                if (window.confirm("Are you sure you want to clear all projects? This cannot be undone.")) {
                  setProjects(MOCK_PROJECTS);
                  setProfile(DEFAULT_PROFILE);
                  localStorage.removeItem(STORAGE_KEY);
                  localStorage.removeItem(PROFILE_KEY);
                }
              }}
              className="text-red-600 text-sm font-medium hover:text-red-700"
            >
              Reset / Clear All Data
            </button>
          </div>
        </div>
      )}
    </Layout>
  );
};

