  const togglePlay = (project: PodcastProject) => {
    if (!project.audioUrl) return;

    if (playingId === project.id && audioEl) {
      if (audioEl.paused) {
        audioEl.play();
      } else {
        audioEl.pause();
        setPlayingId(null);
      }
    } else {
      if (audioEl) {
        audioEl.pause();
      }
      const newAudio = new Audio(project.audioUrl);
      newAudio.play();
      newAudio.onended = () => setPlayingId(null);
      setAudioEl(newAudio);
      setPlayingId(project.id);
    }
  };

