                           <img src={`https://source.unsplash.com/random/800x600?mic,studio&sig=${idx}`} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 opacity-60" />
                        )}

                        <div className="absolute top-4 left-4 z-20 flex gap-2">
                           <span className="px-3 py-1 bg-black/50 backdrop-blur border border-white/20 rounded-full text-[10px] uppercase font-bold tracking-wider">
                              {ep.metadata.genre || 'Podcast'}
                           </span>
                           <span className="px-3 py-1 bg-white/10 backdrop-blur border border-white/20 rounded-full text-[10px] uppercase font-bold tracking-wider">
                              Ep {ep.metadata.episode || idx + 1}
                           </span>
                        </div>
                     </div>

                     {/* Content Bottom Half */}
                     <div className="p-6 relative z-20 -mt-12">
                        <div className="flex items-center gap-2 mb-2">
                           <Headphones className="w-4 h-4 text-slate-400" />
                           <span className="text-xs text-slate-400">{profile.name}</span>
                        </div>
                        <h3 className="text-xl font-bold mb-4 line-clamp-2 leading-tight group-hover:text-purple-400 transition-colors">
                           {ep.title}
                        </h3>

                        <button 
                           onClick={() => togglePlay(ep)}
                           className="flex items-center gap-2 text-sm font-semibold border border-white/20 rounded-full px-4 py-2 hover:bg-white hover:text-black transition-all w-fit"
                        >
                           {playingId === ep.id ? (
                              <><Pause className="w-4 h-4 fill-current" /> Pause</>
                           ) : (
                              <><Play className="w-4 h-4 fill-current" /> Listen Now</>
                           )}
                        </button>
                     </div>
                  </div>
               )) : (
                  <div className="col-span-3 text-center py-12 text-slate-500">
                     No episodes published yet. Check back soon.
                  </div>
               )}
            </div>
         </div>
      </section>

      {/* --- FOOTER / CONTACT --- */}
      <section id="contact" className="py-24 bg-black border-t border-white/10">
         <div className="max-w-4xl mx-auto px-6 text-center">
             <div className="bg-[#0f0f0f] border border-white/10 rounded-3xl p-12 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-purple-900/10 rounded-full blur-3xl"></div>

                <h2 className="text-4xl font-bold mb-4 relative z-10">Get in Touch</h2>
                <p className="text-slate-400 mb-8 max-w-lg mx-auto relative z-10">
                   Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna.
                </p>

                <div className="flex flex-col sm:flex-row gap-4 max-w-md mx-auto relative z-10">
                   <input 
                     type="email" 
                     placeholder="Your Email" 
                     className="flex-1 bg-black border border-white/20 rounded-full px-6 py-3 text-sm focus:outline-none focus:border-purple-500 transition-colors"
                   />
                   <button className="bg-white text-black font-bold px-8 py-3 rounded-full hover:bg-slate-200 transition-colors">
                      Subscribe
                   </button>
                </div>
             </div>

             <div className="mt-16 grid grid-cols-2 md:grid-cols-4 gap-8 text-left border-t border-white/10 pt-12">
                <div>
                   <h3 className="font-bold text-lg mb-4">Podcastly</h3>
                   <p className="text-xs text-slate-500 leading-relaxed">
                      Lorem ipsum is simply dummy text of the printing and typesetting industry.
                   </p>
                </div>
                <div>
                   <h4 className="font-bold text-sm mb-4">Pages</h4>
                   <ul className="space-y-2 text-xs text-slate-400">
                      <li><a href="#" className="hover:text-white">Episodes</a></li>
                      <li><a href="#" className="hover:text-white">Contact</a></li>
                      <li><a href="#" className="hover:text-white">About</a></li>
                      <li><a href="#" className="hover:text-white">Blog</a></li>
                   </ul>
                </div>
                <div>
                   <h4 className="font-bold text-sm mb-4">Utility</h4>
                   <ul className="space-y-2 text-xs text-slate-400">
                      <li><a href="#" className="hover:text-white">Instructions</a></li>
                      <li><a href="#" className="hover:text-white">Style Guide</a></li>
                      <li><a href="#" className="hover:text-white">Changelog</a></li>
                      <li><a href="#" className="hover:text-white">Licenses</a></li>
                   </ul>
                </div>
                <div>
                   <h4 className="font-bold text-sm mb-4">Social Links</h4>
                   <div className="flex gap-4">
                      <a href="#" className="text-slate-400 hover:text-white"><Instagram className="w-5 h-5" /></a>
                      <a href="#" className="text-slate-400 hover:text-white"><Twitter className="w-5 h-5" /></a>
                      <a href="#" className="text-slate-400 hover:text-white"><Facebook className="w-5 h-5" /></a>
                      <a href="#" className="text-slate-400 hover:text-white"><Linkedin className="w-5 h-5" /></a>
                   </div>
                </div>
             </div>

             <div className="mt-12 text-xs text-slate-600 flex justify-between items-center border-t border-white/5 pt-6">
                <span>© 2023 Podcastly. All Rights Reserved.</span>
                <span>Powered by <span className="text-slate-400">StemGolf</span></span>
             </div>
         </div>
      </section>

      {/* Hidden Audio Element */}
      <audio ref={ref => setAudioEl(ref)} src={playingId ? projects.find(p => p.id === playingId)?.audioUrl : undefined} onEnded={() => setPlayingId(null)} />
    </div>
  );
};

export default PublicPage;

export interface Chapter {
  id: string;
  title: string;
  timestamp: number; // Seconds from start of voice track
}

export interface ProductionSettings {
  introMusic?: 'news' | 'story' | 'upbeat' | 'none';
  outroMusic?: 'news' | 'story' | 'upbeat' | 'none';
  playbackSpeed: number; // 0.5 to 2.0
  pitch: number; // -12 to 12 semitones (simulated via rate or detune)
  musicVolume?: number;
  voiceVolume?: number; // 0.0 to 2.0
}

export interface DistributionMetadata {
  author: string;
  genre: string;
  season: number;
  episode: number;
  type: 'full' | 'trailer' | 'bonus';
  explicit: boolean;
  coverArt?: string; // Data URL or URL
  publishDate?: string; // ISO String for scheduling
}

export interface PodcastProject {
  id: string;
  title: string;
  description: string;
  content: string;
  audioUrl?: string;
  createdAt: number;
  duration?: number; // in seconds
  voice: string;
  tone: 'formal' | 'conversational' | 'storytelling';
  productionSettings: ProductionSettings;
  chapters: Chapter[];
  // New Distribution Fields
  metadata: DistributionMetadata;
  distributionStatus: 'draft' | 'scheduled' | 'published' | 'failed';
  platforms?: string[]; // List of IDs like 'spotify', 'apple'
}

export interface CreatorProfile {
  name: string;
  slug: string;
  bio: string;
  coverImage?: string;
  brandColor: string; // Hex
  links: {
    spotify?: string;
    apple?: string;
    rss?: string;
    website?: string;
  };
  // Visual Customization
  theme: 'classic' | 'minimal' | 'bold';
  font: 'modern' | 'serif';
  // Pro Features
  customDomain?: string;
  removeBranding: boolean;
}

export interface BlogPost {
  id: string;
  title: string;
  excerpt: string;
  content: string;
  author: string;
  date: string;
  coverImage?: string;
  tags: string[];
}

export interface VoiceOption {
  id: string;
  name: string;
  gender: 'Male' | 'Female';
  style: string;
}

export enum AppRoute {
  DASHBOARD = 'dashboard',
  STUDIO = 'studio',
  ANALYTICS = 'analytics',
  SETTINGS = 'settings',
  CREATOR_SETTINGS = 'creator_settings',
  PUBLIC_PAGE = 'public_page'
}

// Gemini specific types usually come from the SDK, but we define internal mapped types here
export type GenerationStatus = 'idle' | 'generating_script' | 'synthesizing_audio' | 'mixing' | 'ready' | 'error' | 'publishing';

import React, { useState, useEffect, useRef } from 'react';
import { PodcastProject, GenerationStatus, ProductionSettings, Chapter, DistributionMetadata } from '../types';
import Button from '../components/Button';
import { Wand2, Play, Pause, Download, Save, RefreshCw, Volume2, Music, Mic2, Layers, Sliders, Flag, Sparkles, ChevronDown, ChevronUp, Globe, Rss, Calendar, CheckCircle, AlertCircle, Share2, Upload, Image as ImageIcon, FolderOpen, Plus, Copy, Trash2, X, Search, ArrowUpDown } from 'lucide-react';
import { generateAfrikaansScript, synthesizeSpeech, generateImage } from '../services/gemini';
import { mixPodcastAudio, audioBufferToWav } from '../services/audioUtils';
import { generateRSSFeed, downloadRSS } from '../services/rssUtils';

interface StudioProps {
  initialProject?: PodcastProject | null;
  projects: PodcastProject[];
  onSave: (project: PodcastProject) => void;
  onSelectProject: (project: PodcastProject | null) => void;
  onDeleteProject: (id: string) => void;
  onDuplicateProject: (project: PodcastProject) => void;
}

const Studio: React.FC<StudioProps> = ({ 
  initialProject, 
  projects,
  onSave,
  onSelectProject,
  onDeleteProject,
  onDuplicateProject
}) => {
  // UI State
  const [isProjectListOpen, setIsProjectListOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<'date' | 'title'>('date');

  // Project State
  const [title, setTitle] = useState(initialProject?.title || 'Nuwe Episode');
  const [content, setContent] = useState(initialProject?.content || '');
  const [tone, setTone] = useState<'formal' | 'conversational' | 'storytelling'>(initialProject?.tone || 'conversational');
  const [voice, setVoice] = useState(initialProject?.voice || 'Fenrir');
  const [chapters, setChapters] = useState<Chapter[]>(initialProject?.chapters || []);

  // Metadata State
  const [metadata, setMetadata] = useState<DistributionMetadata>(initialProject?.metadata || {
    author: 'My Podcast',
    genre: 'Society & Culture',
    season: 1,
    episode: 1,
    type: 'full',
    explicit: false,
    publishDate: '',
  });

  const [distStatus, setDistStatus] = useState<'draft' | 'scheduled' | 'published' | 'failed'>(initialProject?.distributionStatus || 'draft');
  const [selectedPlatforms, setSelectedPlatforms] = useState<string[]>(initialProject?.platforms || []);

  // AI Gen State (Script)
  const [scriptLength, setScriptLength] = useState<'short' | 'medium' | 'long'>('medium');
  const [scriptTopics, setScriptTopics] = useState('');
  const [showAiOptions, setShowAiOptions] = useState(false);

  // AI Gen State (Image)
  const [showImageGen, setShowImageGen] = useState(false);
  const [imagePrompt, setImagePrompt] = useState('');
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Production State
  const [prodSettings, setProdSettings] = useState<ProductionSettings>(initialProject?.productionSettings || {
    introMusic: 'none',
    outroMusic: 'none',
    playbackSpeed: 1.0,
    pitch: 0,
    musicVolume: 0.5,
    voiceVolume: 1.0
  });

  // System State
  const [activeTab, setActiveTab] = useState<'script' | 'production' | 'distribution'>('script');
  const [status, setStatus] = useState<GenerationStatus>('idle');

  // Audio State
  const [audioUrl, setAudioUrl] = useState<string | null>(initialProject?.audioUrl || null);
  const [rawVoiceBuffer, setRawVoiceBuffer] = useState<AudioBuffer | null>(null); // Store raw voice for remixing
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const projectId = useRef(initialProject?.id || `proj_${Date.now()}`);

  // Sync state with initialProject prop changes (switching projects)
  useEffect(() => {
    if (initialProject) {
      setTitle(initialProject.title);
      setContent(initialProject.content);
      setTone(initialProject.tone);
      setVoice(initialProject.voice);
      setChapters(initialProject.chapters);
      setMetadata(initialProject.metadata);
      setDistStatus(initialProject.distributionStatus);
      setSelectedPlatforms(initialProject.platforms || []);
      setProdSettings({
        ...initialProject.productionSettings,
        voiceVolume: initialProject.productionSettings.voiceVolume ?? 1.0
      });
      setAudioUrl(initialProject.audioUrl || null);
      projectId.current = initialProject.id;
      setRawVoiceBuffer(null); // Clear raw buffer as we don't store it persistently
    } else {
      // Reset for New Project
      setTitle('Nuwe Episode');
      setContent('');
      setTone('conversational');
      setVoice('Fenrir');
      setChapters([]);
      setMetadata({
        author: 'My Podcast',
        genre: 'Society & Culture',
        season: 1,
        episode: 1,
        type: 'full',
        explicit: false,
        publishDate: '',
      });
      setDistStatus('draft');
      setSelectedPlatforms([]);
      setProdSettings({
        introMusic: 'none',
        outroMusic: 'none',
        playbackSpeed: 1.0,
        pitch: 0,
        musicVolume: 0.5,
        voiceVolume: 1.0
      });
      setAudioUrl(null);
      setRawVoiceBuffer(null);
      projectId.current = `proj_${Date.now()}`;
    }
    // Stop playback if playing
    if (audioRef.current) {
        audioRef.current.pause();
        setIsPlaying(false);
    }
    // Close sidebar on selection on mobile (optional, but good UX)
    // setIsProjectListOpen(false); // Keep open for desktop
  }, [initialProject]);

  // Filter and Sort Projects
  const filteredProjects = projects
    .filter(p => p.title.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => {
      if (sortBy === 'date') {
        return b.createdAt - a.createdAt; // Newest first
      } else {
        return a.title.localeCompare(b.title); // Alphabetical
      }
    });

  // --- Handlers ---

  const handleGenerateScript = async () => {
    if (!content.trim()) return;
    setStatus('generating_script');
    try {
      const improvedScript = await generateAfrikaansScript(content, tone, scriptLength, scriptTopics);
      setContent(improvedScript);
      setStatus('idle');
      setShowAiOptions(false);
    } catch (e) {
      alert("Failed to generate script. Please check your API key.");
      setStatus('error');
    }
  };

  const handleSynthesize = async () => {
    if (!content.trim()) return;
    setStatus('synthesizing_audio');
    try {
      const result = await synthesizeSpeech(content, voice);
      setRawVoiceBuffer(result.buffer); // Save raw buffer for mixing

      // Perform initial mix (defaults)
      await performMix(result.buffer);

      setStatus('ready');
    } catch (e) {
      alert("Failed to synthesize audio.");
      setStatus('error');
    }
  };

  const performMix = async (bufferToMix: AudioBuffer | null = rawVoiceBuffer) => {
    if (!bufferToMix) return;
    setStatus('mixing');
    try {
      const mixedBuffer = await mixPodcastAudio(
        bufferToMix,
        prodSettings.introMusic || 'none',
        prodSettings.outroMusic || 'none',
        prodSettings.playbackSpeed,
        prodSettings.musicVolume ?? 0.5,
        prodSettings.voiceVolume ?? 1.0
      );

      const wavBlob = audioBufferToWav(mixedBuffer);
      const newUrl = URL.createObjectURL(wavBlob);
      setAudioUrl(newUrl);
      setStatus('ready');
    } catch (e) {
      console.error(e);
      setStatus('error');
    }
  };

  // Debounced Mix update when settings change
  useEffect(() => {
    if (status === 'ready' && rawVoiceBuffer) {
      const timer = setTimeout(() => {
        performMix(rawVoiceBuffer);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [prodSettings.introMusic, prodSettings.outroMusic, prodSettings.playbackSpeed, prodSettings.musicVolume, prodSettings.voiceVolume]);

  const togglePlayback = () => {
    if (!audioRef.current || !audioUrl) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleSave = () => {
    onSave({
      id: projectId.current,
      title,
      description: content.slice(0, 100) + '...',
      content,
      audioUrl: audioUrl || undefined,
      createdAt: initialProject?.createdAt || Date.now(),
      duration: rawVoiceBuffer?.duration,
      voice,
      tone,
      productionSettings: prodSettings,
      chapters,
      metadata,
      distributionStatus: distStatus,
      platforms: selectedPlatforms
    });
    alert("Projek gestoor!");
  };

  const handlePublish = async () => {
    if (!audioUrl) return alert("Please generate audio before publishing.");

    setStatus('publishing');

    // Simulate API call delay
    await new Promise(r => setTimeout(r, 2000));

    setDistStatus(metadata.publishDate ? 'scheduled' : 'published');
    setStatus('idle');

    handleSave(); // Save final state

    // Auto-generate RSS for download (since we don't have a backend to host it)
    if (window.confirm("Publishing Successful! Would you like to download your RSS feed and distribution assets now?")) {
        const fullProject = {
          id: projectId.current,
          title,
          description: content.slice(0, 100) + '...',
          content,
          createdAt: initialProject?.createdAt || Date.now(),
          duration: rawVoiceBuffer?.duration,
          voice,
          tone,
          productionSettings: prodSettings,
          chapters,
          metadata,
          distributionStatus: 'published',
        } as PodcastProject;

        const rssXml = generateRSSFeed(fullProject, 5000000); // Mock size
        downloadRSS(rssXml, 'feed.xml');
    }
  };

  const togglePlatform = (id: string) => {
    if (selectedPlatforms.includes(id)) {
      setSelectedPlatforms(prev => prev.filter(p => p !== id));
    } else {
      setSelectedPlatforms(prev => [...prev, id]);
    }
  };

  const insertChapter = () => {
    const name = prompt("Chapter Name:");
    if (name) {
      setContent(prev => prev + `\n\n[Chapter: ${name}]\n`);
    }
  };

  // Image Handlers
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setMetadata({ ...metadata, coverArt: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateImage = async () => {
    if (!imagePrompt) return;
    setIsGeneratingImage(true);
    try {
      const base64Image = await generateImage(imagePrompt);
      setMetadata({ ...metadata, coverArt: base64Image });
      setIsGeneratingImage(false);
      setShowImageGen(false);
    } catch (e) {
      alert("Failed to generate image. Please check API key.");
      setIsGeneratingImage(false);
    }
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col gap-6 relative">

      {/* SIDEBAR OVERLAY */}
      {isProjectListOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden" 
          onClick={() => setIsProjectListOpen(false)}
        ></div>
      )}

      {/* SIDEBAR DRAWER (Dark) */}
      <div 
        className={`absolute top-0 bottom-0 left-0 z-30 w-80 bg-[#121212] border-r border-[#272727] shadow-2xl transform transition-transform duration-300 ease-in-out flex flex-col ${isProjectListOpen ? 'translate-x-0' : '-translate-x-full lg:hidden'}`}
      >
         <div className="p-4 border-b border-[#272727] flex items-center justify-between bg-[#181818]">
           <h3 className="font-bold text-white">My Projects</h3>
           <button onClick={() => setIsProjectListOpen(false)} className="lg:hidden p-1 rounded hover:bg-[#272727] text-slate-400">
             <X className="w-5 h-5" />
           </button>
         </div>

         {/* Search & Sort Controls */}
         <div className="p-3 border-b border-[#272727] space-y-2 bg-[#181818]">
            <div className="relative">
                <Search className="absolute left-2.5 top-2.5 w-4 h-4 text-slate-500" />
                <input 
                  type="text" 
                  placeholder="Search projects..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full bg-[#1f1f1f] border border-[#333] text-sm rounded-lg pl-9 pr-2 py-2 text-white focus:border-orange-500 focus:outline-none focus:ring-1 focus:ring-orange-500"
                />
            </div>
            <div className="flex items-center justify-between text-xs text-slate-400 px-1">
                <span className="flex items-center gap-1"><ArrowUpDown className="w-3 h-3" /> Sort by:</span>
                <select 
                  value={sortBy} 
                  onChange={(e) => setSortBy(e.target.value as 'date' | 'title')}
                  className="bg-transparent border-none text-slate-300 focus:ring-0 p-0 text-xs cursor-pointer"
                >
                    <option value="date">Date Created</option>
                    <option value="title">Title (A-Z)</option>
                </select>
            </div>
         </div>

         <div className="p-3 flex-1 overflow-hidden flex flex-col">
            <button 
              onClick={() => { onSelectProject(null); setIsProjectListOpen(false); }}
              className="w-full flex items-center justify-center gap-2 py-2 px-4 bg-orange-600 hover:bg-orange-700 text-white rounded-lg text-sm font-medium mb-4 flex-shrink-0"
            >
              <Plus className="w-4 h-4" /> New Project
            </button>
            <div className="space-y-2 overflow-y-auto custom-scrollbar flex-1 pb-4">
              {filteredProjects.map(p => (
                <div 
                  key={p.id} 
                  className={`group p-3 rounded-lg border transition-all ${projectId.current === p.id ? 'bg-[#1f1f1f] border-orange-600' : 'bg-[#121212] border-[#272727] hover:border-[#444]'}`}
                >
                   <div 
                     className="cursor-pointer" 
                     onClick={() => { onSelectProject(p); setIsProjectListOpen(false); }}
                   >
                     <div className="font-medium text-white text-sm truncate">{p.title}</div>
                     <div className="text-xs text-slate-500 mt-2 flex items-center justify-between">
                       <span>{new Date(p.createdAt).toLocaleDateString()}</span>

                       {/* Status Indicator */}
                       <span className={`flex items-center gap-1.5 px-1.5 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider border ${
                         p.distributionStatus === 'published' 
                           ? 'bg-green-900/20 text-green-400 border-green-800' 
                           : p.distributionStatus === 'scheduled'
                           ? 'bg-blue-900/20 text-blue-400 border-blue-800'
                           : 'bg-slate-800 text-slate-400 border-slate-700'
                       }`}>
                          {p.distributionStatus === 'published' && <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>}
                          {p.distributionStatus}
                       </span>
                     </div>
                   </div>
                   <div className="mt-3 pt-2 border-t border-[#272727] flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDuplicateProject(p); }}
                        className="p-1 text-slate-400 hover:text-blue-400 hover:bg-blue-900/20 rounded" 
                        title="Duplicate"
                      >
                        <Copy className="w-3.5 h-3.5" />
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDeleteProject(p.id); }}
                        className="p-1 text-slate-400 hover:text-red-400 hover:bg-red-900/20 rounded" 
                        title="Delete"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                   </div>
                </div>
              ))}
              {filteredProjects.length === 0 && (
                <div className="text-center py-8 text-slate-500 text-sm">
                  {projects.length === 0 ? "No projects yet." : "No projects match your search."}
                </div>
              )}
            </div>
         </div>
      </div>

      {/* Top Bar */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center bg-[#181818] p-4 rounded-xl border border-[#272727]">
        <div className="flex items-center gap-3 w-full sm:w-auto">
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={() => setIsProjectListOpen(!isProjectListOpen)}
            className="text-slate-400 border border-[#333]"
          >
            <FolderOpen className="w-5 h-5" />
          </Button>
          <div className="flex-1">
            <input 
              type="text" 
              value={title} 
              onChange={(e) => setTitle(e.target.value)}
              className="bg-transparent border-none font-bold text-xl text-white focus:ring-0 w-full placeholder-slate-600"
              placeholder="Episode Title..."
            />
