const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<AppRoute>(AppRoute.DASHBOARD);
  const [isLoading, setIsLoading] = useState(true);

  // State
  const [projects, setProjects] = useState<PodcastProject[]>([]);
  const [blogPosts, setBlogPosts] = useState<BlogPost[]>([]);
  const [profile, setProfile] = useState<CreatorProfile>(DEFAULT_PROFILE);

  const [editingProject, setEditingProject] = useState<PodcastProject | null>(null);

  // Initial Data Load
  useEffect(() => {
    // Initialize Pixel
    PixelService.init();
    // Track initial page load
    PixelService.trackPageView();

    const loadData = async () => {
      try {
        const [loadedProjects, loadedBlogs, loadedProfile] = await Promise.all([
          db.projects.list(),
          db.content.list(),
          db.users.getProfile()
        ]);

        // Seed default data if empty (first run)
        if (loadedProjects.length === 0 && loadedBlogs.length === 0 && !loadedProfile) {
          await Promise.all([
             ...MOCK_PROJECTS.map(p => db.projects.save(p)),
             ...MOCK_BLOGS.map(b => db.content.save(b)),
             db.users.saveProfile(DEFAULT_PROFILE)
          ]);
          setProjects(MOCK_PROJECTS);
          setBlogPosts(MOCK_BLOGS);
          setProfile(DEFAULT_PROFILE);
        } else {
          setProjects(loadedProjects);
          setBlogPosts(loadedBlogs);
          if (loadedProfile) setProfile(loadedProfile);
        }
      } catch (e) {
        console.error("Database load error:", e);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handleNavigate = (route: AppRoute) => {
    setCurrentRoute(route);
    PixelService.trackPageView(); // Track route changes as PageViews
    if (route !== AppRoute.STUDIO) {
      setEditingProject(null);
    }
  };

  const handleEditProject = (project: PodcastProject) => {
    setEditingProject(project);
    setCurrentRoute(AppRoute.STUDIO);
  };

  const handleSaveProject = async (project: PodcastProject) => {
    // Track Studio usage (e.g. Content Generated)
    PixelService.trackStudioUsage(project.title, project.duration || 0);

    // Optimistic update
    setProjects(prev => {
      const exists = prev.find(p => p.id === project.id);
      if (exists) return prev.map(p => p.id === project.id ? project : p);
      return [project, ...prev];
    });
    setEditingProject(project);

    // DB Save
    try {
      const savedProject = await db.projects.save(project);
      // Update state with valid blob URL from DB if needed
      setProjects(prev => prev.map(p => p.id === savedProject.id ? savedProject : p));
    } catch (e) {
      console.error("Failed to save project", e);
      alert("Error saving project to database");
    }
  };

  const handleDeleteProject = async (projectId: string) => {
    if (window.confirm("Are you sure you want to delete this project? This cannot be undone.")) {
      setProjects(prev => prev.filter(p => p.id !== projectId));
      if (editingProject?.id === projectId) {
        setEditingProject(null);
      }
      await db.projects.delete(projectId);
    }
  };

  const handleDuplicateProject = async (project: PodcastProject) => {
    const newProject: PodcastProject = {
      ...project,
      id: `proj_${Date.now()}`,
      title: `${project.title} (Copy)`,
      createdAt: Date.now(),
      distributionStatus: 'draft',
      audioUrl: undefined, // Don't copy ephemeral URL
      audioBlob: undefined // Don't duplicate heavy blob automatically, user should regenerate
    };

    setProjects(prev => [newProject, ...prev]);
    await db.projects.save(newProject);
  };

  // Blog Handlers
  const handleSavePost = async (post: BlogPost) => {
    setBlogPosts(prev => {
      const exists = prev.find(p => p.id === post.id);
      if (exists) return prev.map(p => p.id === post.id ? post : p);
      return [post, ...prev];
    });
    await db.content.save(post);
  };

  const handleDeletePost = async (id: string) => {
    if (window.confirm("Delete this post?")) {
      setBlogPosts(prev => prev.filter(p => p.id !== id));
      await db.content.delete(id);
    }
  };

  const handleUpdateProfile = async (newProfile: CreatorProfile) => {
    setProfile(newProfile);
    await db.users.saveProfile(newProfile);
  };

  const handleResetData = async () => {
    if (window.confirm("Are you sure you want to clear all database data? This cannot be undone.")) {
      setIsLoading(true);
      await Promise.all([
        db.projects.clear(),
        db.content.clear(),
        db.users.clear()
      ]);
      setProjects([]);
      setBlogPosts([]);
      setProfile(DEFAULT_PROFILE);
      setIsLoading(false);
      alert("Database cleared.");
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center text-white flex-col gap-4">
        <Loader2 className="w-10 h-10 animate-spin text-orange-500" />
        <p className="text-slate-500 text-sm">Loading Content System...</p>
      </div>
    );
  }

  return (
    <Layout currentRoute={currentRoute} onNavigate={handleNavigate} profile={profile}>
      {currentRoute === AppRoute.DASHBOARD && (
        <Dashboard 
          onNavigate={handleNavigate} 
          projects={projects}
          onEditProject={handleEditProject}
        />
      )}

      {currentRoute === AppRoute.STUDIO && (
        <Studio 
          initialProject={editingProject} 
          projects={projects}
          creatorProfile={profile}
          onSave={handleSaveProject}
          onSelectProject={setEditingProject}
          onDeleteProject={handleDeleteProject}
          onDuplicateProject={handleDuplicateProject}
        />
      )}

      {currentRoute === AppRoute.BLOG_EDITOR && (
        <BlogEditor 
          posts={blogPosts}
          profile={profile}
          onSave={handleSavePost}
          onDelete={handleDeletePost}
        />
      )}

      {currentRoute === AppRoute.ANALYTICS && (
        <Analytics />
      )}

      {currentRoute === AppRoute.CREATOR_SETTINGS && (
        <CreatorSettings 
          profile={profile}
          onUpdate={handleUpdateProfile}
          onNavigate={handleNavigate}
        />
      )}

      {currentRoute === AppRoute.PUBLIC_PAGE && (
        <PublicPage 
          profile={profile}
          projects={projects}
          onNavigate={handleNavigate}
        />
      )}

      {currentRoute === AppRoute.SETTINGS && (
        <div className="max-w-2xl">
          <h1 className="text-2xl font-bold text-slate-900 mb-6">Settings</h1>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-medium mb-4">API Configuration</h2>
            <p className="text-sm text-slate-500 mb-4">
              This application uses the Google Gemini API. Ensure your API key is configured in the environment variables (process.env.API_KEY).
            </p>
            <div className="p-4 bg-slate-50 rounded-lg border border-slate-200 text-sm font-mono text-slate-600 break-all">
              {process.env.API_KEY ? 'API Key is configured ✅' : 'Warning: API_KEY is missing from environment.'}
            </div>
          </div>

          <div className="mt-8 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-medium mb-4">Database Management</h2>
            <p className="text-sm text-slate-500 mb-4">
              Your projects, content, and profile are stored in the browser's IndexedDB.
            </p>
            <button 
              onClick={handleResetData}
              className="text-red-600 text-sm font-medium hover:text-red-700"
            >
              Reset / Clear All Database Data
            </button>
          </div>
        </div>
      )}
    </Layout>
  );
};

