import { initializeApp } from 'firebase/app';
import { 
  getAuth, 
  signInWithPopup, 
  GoogleAuthProvider, 
  FacebookAuthProvider, 
  OAuthProvider,
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signOut as firebaseSignOut,
  onAuthStateChanged,
  User,
  AuthError
} from 'firebase/auth';

// Configuration from environment variables
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY || 'demo-key',
  authDomain: process.env.FIREBASE_AUTH_DOMAIN || 'demo.firebaseapp.com',
  projectId: process.env.FIREBASE_PROJECT_ID || 'demo-project',
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);

// Auth Providers
const googleProvider = new GoogleAuthProvider();
const facebookProvider = new FacebookAuthProvider();
// Spotify requires OIDC configuration in Firebase Console
const spotifyProvider = new OAuthProvider('oidc.spotify'); 
spotifyProvider.addScope('user-read-email');

export interface AuthResponse {
  user: User | null;
  error?: string;
}

export const AuthService = {
  // Social Login
  signInWithGoogle: async (): Promise<AuthResponse> => {
    try {
      const result = await signInWithPopup(auth, googleProvider);
      return { user: result.user };
    } catch (error: any) {
      return { user: null, error: error.message };
    }
  },

  signInWithFacebook: async (): Promise<AuthResponse> => {
    try {
      const result = await signInWithPopup(auth, facebookProvider);
      return { user: result.user };
    } catch (error: any) {
      return { user: null, error: error.message };
    }
  },

  signInWithSpotify: async (): Promise<AuthResponse> => {
    try {
      const result = await signInWithPopup(auth, spotifyProvider);
      return { user: result.user };
    } catch (error: any) {
      return { user: null, error: error.message };
    }
  },

  // Email/Password
  signUpEmail: async (email: string, pass: string): Promise<AuthResponse> => {
    try {
      const result = await createUserWithEmailAndPassword(auth, email, pass);
      return { user: result.user };
    } catch (error: any) {
      return { user: null, error: error.message };
    }
  },

  signInEmail: async (email: string, pass: string): Promise<AuthResponse> => {
    try {
      const result = await signInWithEmailAndPassword(auth, email, pass);
      return { user: result.user };
    } catch (error: any) {
      return { user: null, error: error.message };
    }
  },

  signOut: async () => {
    await firebaseSignOut(auth);
  },

  // State Listener
  onAuthStateChange: (callback: (user: User | null) => void) => {
    return onAuthStateChanged(auth, callback);
  }
};

