const Login: React.FC = () => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const action = isSignUp ? AuthService.signUpEmail : AuthService.signInEmail;
    const { error: authError } = await action(email, password);

    if (authError) {
      setError(authError.replace('Firebase:', '').trim());
      setLoading(false);
    }
    // Success will be handled by onAuthStateChanged in App.tsx
  };

  const handleSocial = async (provider: 'google' | 'facebook' | 'spotify') => {
    setLoading(true);
    setError('');
    let res;
    switch(provider) {
        case 'google': res = await AuthService.signInWithGoogle(); break;
        case 'facebook': res = await AuthService.signInWithFacebook(); break;
        case 'spotify': res = await AuthService.signInWithSpotify(); break;
    }
    if (res?.error) {
        setError(res.error);
        setLoading(false);
