                <span>{error}</span>
            </div>
        )}

        {/* Social Buttons */}
        <div className="space-y-3 mb-8">
            <button 
                onClick={() => handleSocial('google')}
                disabled={loading}
                className="w-full flex items-center justify-center gap-3 bg-white text-black font-medium py-2.5 rounded-lg hover:bg-slate-200 transition-colors disabled:opacity-50"
