                    className="flex items-center justify-center gap-2 bg-[#1DB954] text-black font-medium py-2.5 rounded-lg hover:bg-[#1ed760] transition-colors disabled:opacity-50"
                >
                    <SpotifyIcon /> Spotify
                </button>
            </div>
        </div>

        <div className="relative mb-8">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-[#333]"></div></div>
            <div className="relative flex justify-center text-xs uppercase"><span className="bg-[#121212] px-2 text-slate-500">Or with email</span></div>
