const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<AppRoute>(AppRoute.DASHBOARD);
  const [isLoading, setIsLoading] = useState(true);
  const [user, setUser] = useState<User | null>(null);
  const [authChecked, setAuthChecked] = useState(false);

  // State
  const [projects, setProjects] = useState<PodcastProject[]>([]);
  const [blogPosts, setBlogPosts] = useState<BlogPost[]>([]);
  const [profile, setProfile] = useState<CreatorProfile>(DEFAULT_PROFILE);
  const [editingProject, setEditingProject] = useState<PodcastProject | null>(null);

  // Auth Listener
  useEffect(() => {
    const unsubscribe = AuthService.onAuthStateChange((currentUser) => {
      setUser(currentUser);
      setAuthChecked(true);
    });
    return () => unsubscribe();
  }, []);

  // Initial Data Load
  useEffect(() => {
    if (!authChecked) return;

    // Only load private data if user is logged in
    // However, for this demo app we keep using IDB. 
    // In a real app, we'd fetch data specific to `user.uid`.

    PixelService.init();
    PixelService.trackPageView();

    const loadData = async () => {
      setIsLoading(true);
      try {
        const [loadedProjects, loadedBlogs, loadedProfile] = await Promise.all([
          db.projects.list(),
          db.content.list(),
          db.users.getProfile()
        ]);

        if (loadedProjects.length === 0 && loadedBlogs.length === 0 && !loadedProfile) {
          // Seed defaults
          await Promise.all([
             ...MOCK_PROJECTS.map(p => db.projects.save(p)),
             ...MOCK_BLOGS.map(b => db.content.save(b)),
             db.users.saveProfile(DEFAULT_PROFILE)
          ]);
          setProjects(MOCK_PROJECTS);
          setBlogPosts(MOCK_BLOGS);
          setProfile(DEFAULT_PROFILE);
        } else {
          setProjects(loadedProjects);
          setBlogPosts(loadedBlogs);
          if (loadedProfile) setProfile(loadedProfile);
        }
      } catch (e) {
        console.error("Database load error:", e);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, [authChecked]);

  const handleNavigate = (route: AppRoute) => {
    setCurrentRoute(route);
    PixelService.trackPageView();
    if (route !== AppRoute.STUDIO) {
      setEditingProject(null);
    }
  };

  const handleEditProject = (project: PodcastProject) => {
    setEditingProject(project);
    setCurrentRoute(AppRoute.STUDIO);
  };

  const handleSaveProject = async (project: PodcastProject) => {
    PixelService.trackStudioUsage(project.title, project.duration || 0);
    setProjects(prev => {
      const exists = prev.find(p => p.id === project.id);
      if (exists) return prev.map(p => p.id === project.id ? project : p);
      return [project, ...prev];
    });
    setEditingProject(project);
    await db.projects.save(project);
  };

  const handleDeleteProject = async (projectId: string) => {
    if (window.confirm("Are you sure you want to delete this project?")) {
      setProjects(prev => prev.filter(p => p.id !== projectId));
      if (editingProject?.id === projectId) setEditingProject(null);
      await db.projects.delete(projectId);
    }
  };

  const handleDuplicateProject = async (project: PodcastProject) => {
    const newProject: PodcastProject = {
      ...project,
      id: `proj_${Date.now()}`,
      title: `${project.title} (Copy)`,
      createdAt: Date.now(),
      distributionStatus: 'draft',
      audioUrl: undefined, 
      audioBlob: undefined 
    };
    setProjects(prev => [newProject, ...prev]);
    await db.projects.save(newProject);
  };

  const handleSavePost = async (post: BlogPost) => {
    setBlogPosts(prev => {
      const exists = prev.find(p => p.id === post.id);
      if (exists) return prev.map(p => p.id === post.id ? post : p);
      return [post, ...prev];
    });
    await db.content.save(post);
  };

  const handleDeletePost = async (id: string) => {
    if (window.confirm("Delete this post?")) {
      setBlogPosts(prev => prev.filter(p => p.id !== id));
      await db.content.delete(id);
    }
  };

  const handleUpdateProfile = async (newProfile: CreatorProfile) => {
    setProfile(newProfile);
    await db.users.saveProfile(newProfile);
  };

  // --- ROUTING LOGIC ---

  if (!authChecked || isLoading) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center text-white flex-col gap-4">
        <Loader2 className="w-10 h-10 animate-spin text-orange-600" />
        <p className="text-slate-500 text-sm">Initializing Creator Studio...</p>
      </div>
    );
  }

  // Allow public access to public page regardless of auth
  if (currentRoute === AppRoute.PUBLIC_PAGE) {
    return (
       <Layout currentRoute={currentRoute} onNavigate={handleNavigate} profile={profile}>
          <PublicPage 
            profile={profile}
            projects={projects}
            onNavigate={handleNavigate}
          />
       </Layout>
    );
  }

  // Protect all other routes
  if (!user) {
    return <Login />;
  }

  return (
    <Layout currentRoute={currentRoute} onNavigate={handleNavigate} profile={profile}>
      {currentRoute === AppRoute.DASHBOARD && (
        <Dashboard 
          onNavigate={handleNavigate} 
          projects={projects}
          onEditProject={handleEditProject}
        />
      )}

      {currentRoute === AppRoute.STUDIO && (
        <Studio 
          initialProject={editingProject} 
          projects={projects}
          creatorProfile={profile}
          onSave={handleSaveProject}
          onSelectProject={setEditingProject}
          onDeleteProject={handleDeleteProject}
          onDuplicateProject={handleDuplicateProject}
        />
      )}

      {currentRoute === AppRoute.BLOG_EDITOR && (
        <BlogEditor 
          posts={blogPosts}
          profile={profile}
          onSave={handleSavePost}
          onDelete={handleDeletePost}
        />
      )}

      {currentRoute === AppRoute.ANALYTICS && (
        <Analytics />
      )}

      {currentRoute === AppRoute.CREATOR_SETTINGS && (
        <CreatorSettings 
          profile={profile}
          onUpdate={handleUpdateProfile}
          onNavigate={handleNavigate}
        />
      )}

      {currentRoute === AppRoute.SETTINGS && (
        <div className="max-w-2xl">
          <h1 className="text-2xl font-bold text-slate-900 mb-6">Settings</h1>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-medium mb-4">Account</h2>
            <p className="text-sm text-slate-500 mb-2">Logged in as: {user.email}</p>
            <p className="text-sm text-slate-500 mb-4">UID: {user.uid}</p>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { Mic2, LayoutDashboard, Settings, Menu, X, Globe, BarChart3, Search, User, Zap, Radio, HelpCircle, FileText, LogOut } from 'lucide-react';
import { AppRoute, CreatorProfile } from '../types';
import { AuthService } from '../services/auth';

interface LayoutProps {
  children: React.ReactNode;
  currentRoute: AppRoute;
  onNavigate: (route: AppRoute) => void;
  profile?: CreatorProfile; 
}

const Layout: React.FC<LayoutProps> = ({ children, currentRoute, onNavigate, profile }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Simple name fallback
  const displayName = profile?.name || 'Creator';
  const displayInitials = displayName.split(' ').map(n => n[0]).join('').substring(0,2).toUpperCase();

  // If we are on the public page, render a simplified layout
  if (currentRoute === AppRoute.PUBLIC_PAGE) {
    return (
      <div className="min-h-screen bg-slate-950 text-white">
        {children}
      </div>
    );
  }

  const navItems = [
    { id: AppRoute.DASHBOARD, label: 'Discover / Dashboard', icon: LayoutDashboard },
    { id: AppRoute.STUDIO, label: 'Studio (Your Podcasts)', icon: Mic2, badge: 'New' },
    { id: AppRoute.BLOG_EDITOR, label: 'Blog & Articles', icon: FileText, badge: 'AI' },
    { id: AppRoute.ANALYTICS, label: 'Analytics', icon: BarChart3 },
    { id: AppRoute.CREATOR_SETTINGS, label: 'Creator Page', icon: Globe },
  ];

  const handleSignOut = async () => {
    await AuthService.signOut();
    window.location.reload();
  };

  return (
    <div className="flex h-screen bg-[#0f0f0f] text-slate-200 overflow-hidden font-sans">
      {/* Sidebar for Desktop */}
      <aside className="hidden md:flex flex-col w-64 bg-[#121212] border-r border-[#272727]">
        <div className="p-5 flex items-center gap-2">
          <div className="w-8 h-8 bg-orange-600 rounded flex items-center justify-center text-white font-bold text-lg">
            S
          </div>
          <span className="text-lg font-bold tracking-tight text-white">StemGolf</span>
        </div>

        <div className="flex-1 overflow-y-auto py-2">
           <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Your Library</div>
           <nav className="space-y-1 mb-6">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => onNavigate(item.id)}
                className={`w-full flex items-center justify-between px-4 py-2.5 text-sm font-medium transition-colors border-l-2 ${
                  currentRoute === item.id 
                    ? 'border-orange-500 bg-[#1f1f1f] text-white' 
                    : 'border-transparent text-slate-400 hover:text-white hover:bg-[#181818]'
                }`}
              >
                <div className="flex items-center gap-3">
                   <item.icon className={`w-4 h-4 ${currentRoute === item.id ? 'text-orange-500' : 'text-slate-500'}`} />
                   {item.label}
                </div>
                {item.badge && (
                   <span className={`text-[10px] text-white px-1.5 py-0.5 rounded font-bold ${item.badge === 'AI' ? 'bg-purple-600' : 'bg-blue-600'}`}>
                      {item.badge}
                   </span>
                )}
              </button>
            ))}
          </nav>

          <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">For Podcasters</div>
          <nav className="space-y-1 mb-6">
             <button className="w-full flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-slate-400 hover:text-white hover:bg-[#181818] border-l-2 border-transparent">
                <Radio className="w-4 h-4 text-slate-500" />
                Distribution
             </button>
             <button className="w-full flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-slate-400 hover:text-white hover:bg-[#181818] border-l-2 border-transparent">
                <Zap className="w-4 h-4 text-slate-500" />
                Monetization
             </button>
          </nav>

          <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Platform</div>
          <nav className="space-y-1">
             <button 
                onClick={() => onNavigate(AppRoute.SETTINGS)}
                className={`w-full flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-slate-400 hover:text-white hover:bg-[#181818] border-l-2 border-transparent ${currentRoute === AppRoute.SETTINGS ? 'text-white' : ''}`}
             >
                <Settings className="w-4 h-4 text-slate-500" />
                Settings
             </button>
             <button className="w-full flex items-center gap-3 px-4 py-2.5 text-sm font-medium text-slate-400 hover:text-white hover:bg-[#181818] border-l-2 border-transparent">
                <HelpCircle className="w-4 h-4 text-slate-500" />
                Help & Support
             </button>
          </nav>
        </div>

        <div className="p-4 border-t border-[#272727]">
          {/* User Profile */}
          <div className="w-full">
            <div className="flex items-center gap-3 mb-3">
              <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-xs font-medium text-white border border-slate-600">
                {displayInitials}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-white truncate">{displayName}</p>
                <p className="text-xs text-slate-500 truncate">Pro Plan</p>
              </div>
            </div>
            <button 
                onClick={handleSignOut} 
                className="w-full flex items-center justify-center gap-2 text-xs text-red-400 hover:text-red-300 py-1.5 hover:bg-red-900/10 rounded transition-colors"
            >
                <LogOut className="w-3 h-3" /> Sign Out
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Wrapper */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0f0f0f]">

          {/* Header */}
          <header className="h-16 border-b border-[#272727] flex items-center justify-between px-6 bg-[#121212]">
             <div className="md:hidden flex items-center gap-2">
               <div className="w-7 h-7 bg-orange-600 rounded flex items-center justify-center text-white font-bold">S</div>
               <span className="font-bold text-white">StemGolf</span>
             </div>

             {/* Search Bar */}
             <div className="flex-1 max-w-2xl mx-auto px-4 hidden md:block">
               <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                  <input 
                    type="text" 
                    placeholder="Search projects, scripts, or analytics..." 
                    className="w-full bg-[#1f1f1f] border border-[#333] text-slate-200 text-sm rounded-full py-2 pl-10 pr-4 focus:outline-none focus:border-orange-600 focus:ring-1 focus:ring-orange-600 placeholder-slate-600"
                  />
               </div>
             </div>

             <div className="flex items-center gap-3">
                <button 
                  onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                  className="p-2 text-slate-400 hover:text-white md:hidden"
                >
                  {isMobileMenuOpen ? <X /> : <Menu />}
                </button>
             </div>
          </header>

          {/* Mobile Menu Overlay */}
          {isMobileMenuOpen && (
            <div className="md:hidden fixed inset-0 bg-[#121212] z-50 pt-20 px-4">
              <button 
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="absolute top-4 right-4 p-2 text-slate-400"
              >
                  <X />
              </button>
              <nav className="space-y-2">
                {navItems.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => {
                      onNavigate(item.id);
                      setIsMobileMenuOpen(false);
                    }}
                    className={`w-full flex items-center gap-3 px-4 py-4 text-base font-medium rounded-lg border ${
                      currentRoute === item.id 
                        ? 'bg-[#1f1f1f] border-orange-500 text-white' 
                        : 'bg-transparent border-[#333] text-slate-400'
                    }`}
                  >
                    <item.icon className="w-5 h-5" />
                    {item.label}
                  </button>
                ))}

                <div className="pt-4 mt-4 border-t border-[#333]">
                    <button 
                        onClick={handleSignOut}
                        className="w-full flex items-center gap-3 px-4 py-3 text-base font-medium text-red-400"
                    >
                        <LogOut className="w-5 h-5" /> Sign Out
                    </button>
                </div>
              </nav>
            </div>
          )}

          {/* Main Content Area */}
          <main className="flex-1 overflow-auto p-6 md:p-8 custom-scrollbar">
            {children}
          </main>
      </div>
    </div>
  );
};

export default Layout;

