            createdAt: Date.now(),
            tags: blogData.tags,
            status: 'draft',
            coverImage: metadata.coverArt,
            linkedEpisodeId: projectId.current
         };
         onCreateBlogPost(newPost);
         console.log("Blog post auto-generated");
