                               <input 
                                  type="number" 
                                  value={metadata.episode}
                                  onChange={e => setMetadata({...metadata, episode: parseInt(e.target.value)})}
                                  className="mt-1 w-full bg-[#121212] text-white rounded-md border-[#333] shadow-sm focus:border-orange-500 focus:ring-orange-500"
                               />
                            </div>
                         </div>

                         <div>
                            <label className="block text-sm font-medium text-slate-400">Episode Type</label>
                            <select
                               value={metadata.type}
                               onChange={e => setMetadata({...metadata, type: e.target.value as any})}
                               className="mt-1 w-full bg-[#121212] text-white rounded-md border-[#333] shadow-sm focus:border-orange-500 focus:ring-orange-500"
                            >
                               <option value="full">Full Episode</option>
                               <option value="trailer">Trailer</option>
                               <option value="bonus">Bonus</option>
                            </select>
                         </div>

                         <div className="flex items-center gap-2 pt-2">
                            <input 
                               type="checkbox" 
                               id="explicit"
                               checked={metadata.explicit}
                               onChange={e => setMetadata({...metadata, explicit: e.target.checked})}
                               className="rounded border-[#333] bg-[#121212] text-orange-600 focus:ring-orange-500"
                            />
                            <label htmlFor="explicit" className="text-sm text-slate-400">Contains Explicit Content</label>
                         </div>
                      </div>
                   </div>

                   {/* Right Col: Distribution & Scheduling */}
                   <div className="space-y-6">
                      <h3 className="text-lg font-semibold text-white flex items-center gap-2">
                        <Globe className="w-5 h-5 text-orange-600" /> Distribution Channels
                      </h3>

                      <div className="space-y-3">
                         {PLATFORMS.map(platform => {
                            const isSelected = selectedPlatforms.includes(platform.id);
                            const pStatus = platformStatusMap[platform.id] || 'idle';

                            return (
                             <div 
                               key={platform.id}
                               onClick={() => togglePlatform(platform.id, platform.isConnected)}
                               className={`p-4 rounded-xl border flex items-center justify-between cursor-pointer transition-all ${isSelected ? platform.color : 'border-[#333] hover:bg-[#1f1f1f] bg-[#121212]'}`}
                             >
                                <div className="flex items-center gap-4">
                                   <div className={`w-5 h-5 rounded-full border flex items-center justify-center transition-colors ${isSelected ? platform.iconColor : 'border-slate-500'}`}>
                                      {isSelected && <CheckCircle className="w-3.5 h-3.5 text-white" />}
                                   </div>
                                   <div>
                                      <div className="font-medium text-white text-sm">{platform.name}</div>
                                      <div className="flex items-center gap-1.5 mt-0.5">
                                         {platform.isConnected ? (
                                           <span className="text-[10px] text-green-400 flex items-center gap-1"><Link className="w-3 h-3" /> Connected</span>
                                         ) : (
                                           <span className="text-[10px] text-slate-500 flex items-center gap-1"><Link className="w-3 h-3" /> Not Configured</span>
                                         )}
                                      </div>
                                   </div>
                                </div>

                                {/* Status Indicator */}
                                {isSelected && (
                                   <div className="flex items-center">
                                      {pStatus === 'pending' && <Loader2 className="w-5 h-5 text-slate-400 animate-spin" />}
                                      {pStatus === 'success' && <CheckCircle className="w-5 h-5 text-green-500" />}
                                      {pStatus === 'error' && <XCircle className="w-5 h-5 text-red-500" />}
                                   </div>
                                )}
                             </div>
                            );
                         })}
                      </div>

                      <div className="pt-4 border-t border-[#333]">
                         <h4 className="text-sm font-medium text-slate-400 mb-2">Schedule Publishing</h4>
                         <div className="flex gap-2">
                             <input 
                               type="datetime-local" 
                               value={metadata.publishDate}
                               onChange={e => setMetadata({...metadata, publishDate: e.target.value})}
                               className="w-full text-sm bg-[#121212] text-white rounded-md border-[#333] focus:border-orange-500 focus:ring-orange-500"
                             />
                         </div>
                         <p className="text-xs text-slate-500 mt-2">
                            {metadata.publishDate ? 'Episode will be released automatically at this time.' : 'Episode will be published immediately.'}
                         </p>
                      </div>

                      <div className="pt-4 border-t border-[#333]">
                          <div className="flex items-center justify-between">
                            <div>
                                <h4 className="text-sm font-medium text-slate-400">Content Repurposing</h4>
                                <p className="text-xs text-slate-500">Automatically create a blog post draft from script.</p>
                            </div>
                            <div className="flex items-center gap-2">
                                <label className="flex items-center cursor-pointer">
                                    <input 
                                        type="checkbox"
                                        checked={autoGenBlog}
                                        onChange={(e) => setAutoGenBlog(e.target.checked)}
                                        className="sr-only peer"
                                    />
                                    <div className="w-11 h-6 bg-[#333] peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-orange-600 relative"></div>
                                </label>
                            </div>
                          </div>
                      </div>
                   </div>
                </div>

                {/* Publish Action Area */}
                <div className="mt-8 pt-8 border-t border-[#333] flex flex-col items-center justify-center text-center">
                   {distStatus === 'published' ? (
                      <div className="bg-green-900/20 border border-green-800 rounded-xl p-6 w-full max-w-lg">
                         <div className="mx-auto w-12 h-12 bg-green-800/50 text-green-400 rounded-full flex items-center justify-center mb-3">
                            <CheckCircle className="w-6 h-6" />
                         </div>
                         <h3 className="text-xl font-bold text-green-400">Published Successfully!</h3>
                         <p className="text-green-300 mt-1 mb-4">Your episode is now live on selected platforms.</p>
                         <Button variant="secondary" onClick={() => setDistStatus('draft')}>Publish Update</Button>
                      </div>
                   ) : distStatus === 'scheduled' ? (
                       <div className="bg-blue-900/20 border border-blue-800 rounded-xl p-6 w-full max-w-lg">
                         <div className="mx-auto w-12 h-12 bg-blue-800/50 text-blue-400 rounded-full flex items-center justify-center mb-3">
                            <Calendar className="w-6 h-6" />
                         </div>
                         <h3 className="text-xl font-bold text-blue-400">Scheduled for Release</h3>
                         <p className="text-blue-300 mt-1 mb-4">Scheduled for: {new Date(metadata.publishDate || '').toLocaleString()}</p>
                         <Button variant="secondary" onClick={() => setDistStatus('draft')}>Cancel Schedule</Button>
                      </div>
                   ) : (
                     <div className="w-full max-w-lg space-y-4">
                        {!audioUrl && (
                           <div className="flex items-center gap-2 text-amber-500 bg-amber-900/20 p-3 rounded-lg text-sm mb-2 border border-amber-800">
                              <AlertCircle className="w-4 h-4" />
                              Audio must be generated before publishing.
                           </div>
                        )}
                        <Button 
                           size="lg" 
                           className="w-full text-lg py-4 shadow-lg shadow-orange-900/10"
                           disabled={!audioUrl || selectedPlatforms.length === 0}
                           isLoading={status === 'publishing'}
                           onClick={handlePublish}
                        >
                           {status === 'publishing' ? 'Distributing to Platforms...' : 'Publish Episode Now'}
                        </Button>
                        <p className="text-xs text-slate-500">
                           By publishing, you confirm that you own all rights to the content.
                        </p>
                     </div>
                   )}
                </div>
             </div>
          )}
        </div>

        {/* RIGHT COLUMN: PREVIEW & EXPORT */}
        <div className="lg:w-80 flex flex-col gap-6">
           {/* ... Output content unchanged ... */}
           <div className="bg-[#181818] rounded-xl border border-[#272727] p-6 flex flex-col h-full">
              <h3 className="font-semibold text-white mb-6">Final Output</h3>

              <div className="flex-1 bg-black rounded-xl p-6 relative flex flex-col items-center justify-center text-center text-white mb-6 overflow-hidden border border-[#333]">
                  <div className="absolute inset-0 bg-gradient-to-br from-[#1a1a1a] to-black"></div>
                  <div className="absolute bottom-0 left-0 right-0 h-16 flex items-end justify-center gap-1 opacity-20 px-4">
                     {[...Array(12)].map((_, i) => (
                       <div key={i} className={`w-full bg-orange-500 rounded-t-sm transition-all duration-300 ${isPlaying ? 'animate-pulse' : ''}`} style={{ height: `${Math.random() * 80 + 20}%` }}></div>
                     ))}
                  </div>

                  <div className="z-10 relative">
                    {audioUrl ? (
                      <>
                        <button 
                          onClick={togglePlayback}
                          className="w-16 h-16 bg-orange-600 hover:bg-orange-500 rounded-full flex items-center justify-center mb-4 transition-transform hover:scale-105 shadow-xl shadow-orange-900/20"
                        >
                          {isPlaying ? <Pause className="w-8 h-8 fill-current" /> : <Play className="w-8 h-8 fill-current ml-1" />}
                        </button>
                        <div className="text-sm font-medium text-slate-300">
                          {Math.floor((audioRef.current?.duration || 0) / 60)}:
                          {Math.floor((audioRef.current?.duration || 0) % 60).toString().padStart(2, '0')}
                        </div>
                      </>
                    ) : (
                      <div className="text-slate-600 text-sm">
                        No audio generated yet
                      </div>
                    )}
                  </div>

                  <audio 
                    ref={audioRef} 
                    src={audioUrl || undefined} 
                    onEnded={() => setIsPlaying(false)}
                    onTimeUpdate={() => { /* Force re-render for time if needed */ }}
                  />
              </div>

              <div className="space-y-3">
                 {!rawVoiceBuffer ? (
                   <Button 
                     className="w-full" 
                     onClick={handleSynthesize} 
                     isLoading={status === 'synthesizing_audio'}
                     disabled={!content.trim()}
                   >
                     <RefreshCw className="w-4 h-4 mr-2" />
                     Generate Audio
                   </Button>
                 ) : (
                   <Button 
                      className="w-full" 
                      onClick={handleSynthesize} 
                      variant="secondary"
                      isLoading={status === 'synthesizing_audio'}
                    >
                      <RefreshCw className="w-4 h-4 mr-2" />
                      Re-Generate Voice
                    </Button>
                 )}

                 <a 
                   href={audioUrl || '#'} 
                   download={`${title.replace(/\s+/g, '_')}.wav`}
                   className={`flex items-center justify-center w-full px-4 py-2 rounded-lg font-medium transition-colors ${!audioUrl ? 'bg-[#222] text-slate-600 cursor-not-allowed' : 'bg-white text-black hover:bg-slate-200'}`}
                   onClick={(e) => !audioUrl && e.preventDefault()}
                 >
                   <Download className="w-4 h-4 mr-2" />
                   Export WAV
                 </a>
                 <p className="text-xs text-center text-slate-500">High Quality 24kHz WAV</p>
              </div>
           </div>
        </div>

      </div>
    </div>
  );
};

export default Studio;

import React, { useState, useRef } from 'react';
import { BlogPost, CreatorProfile, PodcastProject } from '../types';
import Button from '../components/Button';
import { FileText, Plus, Sparkles, Image as ImageIcon, X, Save, ArrowLeft, Wand2, Calendar, Tag, Trash2, ExternalLink, Link as LinkIcon, Mic } from 'lucide-react';
import { generateBlogContent, generateImage } from '../services/gemini';

interface BlogEditorProps {
  posts: BlogPost[];
  profile: CreatorProfile;
  projects: PodcastProject[];
  onSave: (post: BlogPost) => void;
  onDelete: (id: string) => void;
}

const BlogEditor: React.FC<BlogEditorProps> = ({ posts, profile, projects, onSave, onDelete }) => {
  const [editingPost, setEditingPost] = useState<BlogPost | null>(null);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  // AI State
  const [aiTopic, setAiTopic] = useState('');
  const [aiContext, setAiContext] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  // Editor State
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [excerpt, setExcerpt] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [coverImage, setCoverImage] = useState('');
  const [tagInput, setTagInput] = useState('');
  const [linkedEpisodeId, setLinkedEpisodeId] = useState<string>('');

  const handleCreateNew = () => {
    const newPost: BlogPost = {
      id: `post_${Date.now()}`,
      title: 'New Article',
      excerpt: '',
      content: '',
      author: profile.name,
      date: new Date().toLocaleDateString(),
      createdAt: Date.now(),
      tags: [],
      status: 'draft'
    };
    setEditingPost(newPost);
    syncState(newPost);
  };

  const syncState = (post: BlogPost) => {
    setTitle(post.title);
    setContent(post.content);
    setExcerpt(post.excerpt);
    setTags(post.tags);
    setCoverImage(post.coverImage || '');
    setLinkedEpisodeId(post.linkedEpisodeId || '');
  };

  const handleEdit = (post: BlogPost) => {
    setEditingPost(post);
    syncState(post);
  };

  const handleSaveCurrent = () => {
    if (!editingPost) return;
    const updated: BlogPost = {
      ...editingPost,
      title,
      content,
      excerpt,
      tags,
      coverImage: coverImage || undefined,
      linkedEpisodeId: linkedEpisodeId || undefined,
    };
    onSave(updated);
    setEditingPost(null);
  };

  const handleGenerateAI = async () => {
    if (!aiTopic) return;
    setIsGenerating(true);
    try {
      const result = await generateBlogContent(aiTopic, aiContext);

      setTitle(result.title);
      setContent(result.content);
      setExcerpt(result.excerpt);
      setTags(result.tags);
      setIsAiModalOpen(false);

      // Auto-generate image if none exists
      if (!coverImage) {
         try {
           const img = await generateImage(result.title + " blog post cover minimal artistic");
           setCoverImage(img);
         } catch (e) { console.error("Image gen failed", e); }
      }
    } catch (e) {
      alert("Failed to generate blog content. Check API Key.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenerateFromEpisode = async () => {
     if (!linkedEpisodeId) return;
     const project = projects.find(p => p.id === linkedEpisodeId);
     if (!project || !project.content) {
         alert("Episode not found or has no content.");
         return;
     }

     if (!window.confirm("This will overwrite your current title and content. Continue?")) return;

     setIsGenerating(true);
     try {
         const result = await generateBlogContent(project.title, project.content);
         setTitle(result.title);
         setContent(result.content);
         setExcerpt(result.excerpt);
         setTags(result.tags);
         if (project.metadata.coverArt && !coverImage) {
             setCoverImage(project.metadata.coverArt);
         }
     } catch (e) {
         alert("Failed to generate from episode.");
     } finally {
         setIsGenerating(false);
     }
  };

  const handleAddTag = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && tagInput.trim()) {
      if (!tags.includes(tagInput.trim())) {
        setTags([...tags, tagInput.trim()]);
      }
      setTagInput('');
    }
  };

  const removeTag = (t: string) => {
    setTags(tags.filter(tag => tag !== t));
  };

  // --- RENDER LIST VIEW ---
  if (!editingPost) {
    return (
      <div className="space-y-6">
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold text-white">Blog & Articles</h1>
            <p className="text-slate-400">Manage your Afrikaans written content.</p>
          </div>
          <Button onClick={handleCreateNew}>
            <Plus className="w-4 h-4 mr-2" /> New Article
          </Button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Create with AI Card */}
          <div 
             onClick={handleCreateNew}
             className="group bg-gradient-to-br from-purple-900/20 to-[#181818] border border-purple-500/30 hover:border-purple-500 rounded-xl p-6 flex flex-col items-center justify-center cursor-pointer min-h-[200px] transition-all"
          >
             <div className="w-12 h-12 bg-purple-600/20 text-purple-400 rounded-full flex items-center justify-center mb-4 group-hover:bg-purple-600 group-hover:text-white transition-colors">
                <Wand2 className="w-6 h-6" />
             </div>
             <h3 className="text-white font-bold mb-1">Create with AI</h3>
             <p className="text-xs text-slate-400 text-center">Generate a full article from a topic or transcript.</p>
          </div>

          {posts.map(post => (
            <div key={post.id} className="bg-[#181818] border border-[#272727] rounded-xl overflow-hidden hover:border-slate-500 transition-colors flex flex-col">
               <div className="h-40 bg-[#222] relative overflow-hidden">
                  {post.coverImage ? (
                    <img src={post.coverImage} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center"><FileText className="w-10 h-10 text-slate-600" /></div>
                  )}
                  <div className={`absolute top-2 right-2 px-2 py-1 rounded text-[10px] font-bold uppercase ${post.status === 'published' ? 'bg-green-500 text-black' : 'bg-slate-700 text-white'}`}>
                     {post.status}
                  </div>
                  {post.linkedEpisodeId && (
                     <div className="absolute bottom-2 left-2 px-2 py-1 rounded bg-black/60 text-white text-[10px] font-bold flex items-center gap-1">
                        <Mic className="w-3 h-3" /> Linked
                     </div>
                  )}
               </div>
               <div className="p-4 flex-1 flex flex-col">
                  <h3 className="text-white font-bold text-lg mb-2 line-clamp-1">{post.title}</h3>
                  <p className="text-slate-500 text-sm line-clamp-2 mb-4 flex-1">{post.excerpt || 'No excerpt.'}</p>
                  <div className="flex items-center justify-between mt-auto pt-4 border-t border-[#272727]">
                     <span className="text-xs text-slate-500">{post.date}</span>
                     <div className="flex gap-2">
                        <button onClick={() => onDelete(post.id)} className="p-1.5 hover:bg-red-900/20 text-slate-400 hover:text-red-400 rounded transition-colors"><Trash2 className="w-4 h-4" /></button>
                        <Button size="sm" variant="secondary" onClick={() => handleEdit(post)}>Edit</Button>
                     </div>
                  </div>
               </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // --- RENDER EDITOR VIEW ---
  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col gap-6 relative">

      {/* Top Bar */}
      <div className="flex justify-between items-center bg-[#181818] p-4 rounded-xl border border-[#272727]">
         <div className="flex items-center gap-4">
            <button onClick={() => setEditingPost(null)} className="p-2 hover:bg-[#222] rounded-lg text-slate-400 hover:text-white transition-colors">
               <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="h-6 w-px bg-[#333]"></div>
            <span className="text-sm font-medium text-slate-300">{editingPost.status === 'draft' ? 'Draft' : 'Published'}</span>
         </div>
         <div className="flex gap-3">
            <Button variant="secondary" onClick={() => setIsAiModalOpen(true)}>
               <Sparkles className="w-4 h-4 mr-2 text-purple-400" /> AI Assist
            </Button>
            <Button onClick={handleSaveCurrent}>
               <Save className="w-4 h-4 mr-2" /> Save & Close
            </Button>
         </div>
      </div>

      <div className="flex-1 flex gap-6 overflow-hidden">
         {/* Main Editor */}
         <div className="flex-1 bg-[#181818] rounded-xl border border-[#272727] flex flex-col overflow-hidden">
            <div className="p-6 border-b border-[#272727]">
               <input 
                 type="text" 
                 value={title}
                 onChange={(e) => setTitle(e.target.value)}
                 className="w-full bg-transparent text-3xl font-bold text-white placeholder-slate-600 border-none focus:ring-0 px-0"
                 placeholder="Article Title..."
               />
            </div>
            <div className="flex-1 relative">
               <textarea 
                  value={content}
                  onChange={(e) => setContent(e.target.value)}
                  className="w-full h-full bg-[#121212] text-slate-300 p-6 resize-none border-none focus:ring-0 font-mono text-sm leading-relaxed"
                  placeholder="<p>Write your story here...</p>"
               />
               <div className="absolute bottom-4 right-4 bg-[#222] text-xs text-slate-500 px-2 py-1 rounded border border-[#333]">
                  HTML / Markdown Supported
               </div>
            </div>
         </div>

         {/* Sidebar Metadata */}
         <div className="w-80 space-y-6 overflow-y-auto pr-1">
            <div className="bg-[#181818] rounded-xl border border-[#272727] p-5 space-y-4">
               <div>
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2 block">Cover Image</label>
                  <div className="aspect-video bg-[#121212] rounded-lg border border-[#333] overflow-hidden relative group">
                     {coverImage ? (
                        <img src={coverImage} className="w-full h-full object-cover" />
                     ) : (
                        <div className="w-full h-full flex items-center justify-center"><ImageIcon className="text-slate-600" /></div>
                     )}
                     <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <Button size="sm" variant="secondary" onClick={async () => {
                           const p = prompt("Image Prompt:");
                           if (p) {
                              try { const url = await generateImage(p); setCoverImage(url); } catch(e) { alert("Failed"); }
                           }
                        }}>Change</Button>
                     </div>
                  </div>
               </div>

               <div>
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2 block">Linked Episode</label>
                  <select 
                     value={linkedEpisodeId}
                     onChange={(e) => setLinkedEpisodeId(e.target.value)}
                     className="w-full bg-[#121212] border border-[#333] rounded-lg text-sm text-slate-300 p-2 mb-2"
                  >
                     <option value="">-- None --</option>
                     {projects.map(p => (
                        <option key={p.id} value={p.id}>{p.title}</option>
                     ))}
                  </select>
                  {linkedEpisodeId && (
                     <Button 
                        size="sm" 
                        variant="secondary" 
                        className="w-full text-xs"
                        onClick={handleGenerateFromEpisode}
                        isLoading={isGenerating}
                     >
                        <RefreshCw className="w-3 h-3 mr-2" /> Re-Generate from Episode
                     </Button>
                  )}
               </div>

               <div>
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2 block">Excerpt</label>
                  <textarea 
                     rows={3}
                     value={excerpt}
                     onChange={(e) => setExcerpt(e.target.value)}
                     className="w-full bg-[#121212] border border-[#333] rounded-lg text-sm text-slate-300 p-3 focus:border-orange-500 focus:ring-1 focus:ring-orange-500"
                     placeholder="Short summary..."
                  />
               </div>

               <div>
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2 block">Tags</label>
                  <div className="flex flex-wrap gap-2 mb-2">
                     {tags.map(t => (
                        <span key={t} className="bg-[#222] border border-[#333] text-xs px-2 py-1 rounded flex items-center gap-1">
                           {t} <button onClick={() => removeTag(t)}><X className="w-3 h-3 hover:text-red-400" /></button>
                        </span>
                     ))}
                  </div>
                  <input 
                     value={tagInput}
                     onChange={(e) => setTagInput(e.target.value)}
                     onKeyDown={handleAddTag}
                     className="w-full bg-[#121212] border border-[#333] rounded-lg text-sm text-slate-300 p-2 focus:border-orange-500"
                     placeholder="Add tag and press Enter"
                  />
               </div>

               <div>
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2 block">Status</label>
                  <select 
                     value={editingPost.status} 
                     onChange={(e) => setEditingPost({...editingPost, status: e.target.value as any})}
