      setContent('');
      setTone('conversational');
      setVoice('Fenrir');
      setChapters([]);
      setSelectedSeriesId('');
      setYoutubeMeta(undefined);
      setMetadata({
        author: creatorProfile.name || 'My Podcast',
        genre: 'Society & Culture',
        season: 1,
        episode: 1,
        type: 'full',
        explicit: false,
        publishDate: '',
      });
