      <div className="flex-1 flex gap-6 overflow-hidden">
         {/* Main Editor */}
         <div className="flex-1 bg-[#181818] rounded-xl border border-[#272727] flex flex-col overflow-hidden">
            <div className="p-6 border-b border-[#272727]">
