function loadAudio(url: string, offline: boolean): Promise<AudioBuffer> {
    const context = offline ? new OfflineAudioContext(2, 44100 * 5, 44100) : new (window.AudioContext || (window as any).webkitAudioContext)();
    return fetch(url)
      .then((response) => response.arrayBuffer())
      .then((buffer) => context.decodeAudioData(buffer));
  }

  function mixAudio(
    audioBuffers: AudioBuffer[],
    ctx: BaseAudioContext,
    duration: number,
  ): Promise<AudioBuffer> {
    return new Promise((resolve) => {
      // 1. Create an AudioBuffer to store the result
      const buffer = ctx.createBuffer(
        audioBuffers[0].numberOfChannels,
        duration * audioBuffers[0].sampleRate,
        audioBuffers[0].sampleRate,
      );

      // 2. Mix the audioBuffers into the result buffer
      audioBuffers.forEach((audioBuffer) => {
        // Create an AudioBufferSourceNode for this audioBuffer
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;

        // Create a GainNode to control the volume
        const gainNode = ctx.createGain();
        gainNode.gain.value = 1;
        source.connect(gainNode);
        gainNode.connect(ctx.destination);

        // 3. Start the audio source, and copy the data to the buffer
        source.start();
        const start = 0
        const end = Math.min(duration, audioBuffer.duration);

        for (let channel = 0; channel < buffer.numberOfChannels; channel++) {
          const bufferData = buffer.getChannelData(channel);
          const sourceData = audioBuffer.getChannelData(channel);
          for (let i = 0; i < end * ctx.sampleRate; i++) {
            bufferData[i] = (bufferData[i] || 0) + (sourceData[i] || 0);
          }
        }
      });
      // 4. Resolve the promise with the mixed audio buffer
      resolve(buffer);
    });
  }
