                <div className="p-4 border-b border-[#272727] bg-[#1f1f1f] flex justify-between items-center">
                    <h3 className="font-bold text-white flex items-center gap-2">
                        <TrendingUp className="w-4 h-4 text-blue-500" /> Google Trends
