                        <Button size="sm" variant="secondary" onClick={() => handleEdit(post)}>Edit</Button>
                     </div>
                  </div>
               </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // --- RENDER EDITOR VIEW ---
  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col gap-6 relative">

      {/* Top Bar */}
