                              rows={5}
                              className="w-full bg-[#121212] border border-[#333] rounded-lg p-3 text-white focus:border-purple-500 focus:ring-purple-500 resize-none"
                              placeholder="Paste rough notes, key points, or a brief here..."
                           />
