const DEFAULT_PROFILE: CreatorProfile = {
  name: 'Jan De Vries',
  slug: 'jan-se-nuus',
  bio: 'Bringing you the latest updates and stories from Cape Town in authentic Afrikaans.',
  brandColor: '#ea580c',
