                  className="flex-1 bg-[#1f1f1f] border border-[#333] text-slate-300 text-xs rounded py-1.5 px-2 focus:ring-0 cursor-pointer"
                >
                    <option value="all">All Status</option>
                    <option value="draft">Drafts</option>
