  { name: 'StemGolf Orange', value: '#ea580c' },
  { name: 'Royal Blue', value: '#2563eb' },
  { name: 'Forest Green', value: '#16a34a' },
  { name: 'Berry Purple', value: '#9333ea' },
  { name: 'Slate Dark', value: '#1e293b' },
