const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<AppRoute>(AppRoute.DASHBOARD);
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);

  // State
  const [projects, setProjects] = useState<PodcastProject[]>([]);
  const [blogPosts, setBlogPosts] = useState<BlogPost[]>([]);
  const [seriesList, setSeriesList] = useState<Series[]>([]);
  const [profile, setProfile] = useState<CreatorProfile>(DEFAULT_PROFILE);

  const [editingProject, setEditingProject] = useState<PodcastProject | null>(null);

  // Initial Data Load
  useEffect(() => {
    // Check local session
    const session = localStorage.getItem('stemgolf_session');

    const loadData = async () => {
      try {
        const [loadedProjects, loadedBlogs, loadedSeries, loadedProfile] = await Promise.all([
          db.projects.list(),
          db.content.list(),
          db.series.list(),
          db.users.getProfile()
        ]);

        if (loadedProjects.length === 0 && loadedBlogs.length === 0) {
           // We might seed mock data for projects/blogs even if not logged in for SEO/Public page? 
           // But let's assume we seed them for the demo environment.
           // However, we only seed profile on Login now.
        }

        setProjects(loadedProjects.length > 0 ? loadedProjects : []);
        setBlogPosts(loadedBlogs.length > 0 ? loadedBlogs : []);
        setSeriesList(loadedSeries);

        if (session) {
          setIsAuthenticated(true);
          if (loadedProfile) {
            // Merge loaded profile with default to ensure all fields exist (e.g. plan, role)
            const mergedProfile = { ...DEFAULT_PROFILE, ...loadedProfile };
            setProfile(mergedProfile);
            SEOService.updateTags(mergedProfile.seo);

            // Initialize Pixel with User ID if available
            if (mergedProfile.seo?.facebookPixelId) {
                PixelService.init(mergedProfile.seo.facebookPixelId);
                PixelService.trackPageView();
            } else {
                PixelService.init(); // Default check
                PixelService.trackPageView();
            }
          } else {
              PixelService.init();
              PixelService.trackPageView();
          }
        } else {
           // Not authenticated, redirect to login unless viewing public page (logic handled in render)
           setCurrentRoute(AppRoute.LOGIN);
        }

      } catch (e) {
        console.error("Database load error:", e);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const handleLogin = async (method: 'google' | 'email', email?: string) => {
    setIsAuthLoading(true);
    // Simulate network delay
    await new Promise(r => setTimeout(r, 1500));

    // Create/Ensure profile exists
    let userProfile = await db.users.getProfile();

    // Check for Admin credentials (mocked)
    const isAdmin = email === 'admin@stemgolf.app';

    if (!userProfile) {
      // Seed default profile on first login (Sign Up flow)
      userProfile = {
          ...DEFAULT_PROFILE,
          role: isAdmin ? 'admin' : 'user',
          name: isAdmin ? 'System Admin' : DEFAULT_PROFILE.name
      };
      await db.users.saveProfile(userProfile);

      // Also seed mock projects/blogs if empty
      if (projects.length === 0 && !isAdmin) {
          await Promise.all([
             ...MOCK_PROJECTS.map(p => db.projects.save(p)),
             ...MOCK_BLOGS.map(b => db.content.save(b))
          ]);
          setProjects(MOCK_PROJECTS);
          setBlogPosts(MOCK_BLOGS);
      }
    } else {
        // If profile exists, ensure role is correct based on login
        if (isAdmin && userProfile.role !== 'admin') {
            userProfile.role = 'admin';
            await db.users.saveProfile(userProfile);
        }
    }

    // Merge defaults on login as well
    const mergedProfile = { ...DEFAULT_PROFILE, ...userProfile };

    setProfile(mergedProfile);
    SEOService.updateTags(mergedProfile.seo);

    if (mergedProfile.seo?.facebookPixelId) {
       PixelService.init(mergedProfile.seo.facebookPixelId);
    }

    localStorage.setItem('stemgolf_session', 'true');
    setIsAuthenticated(true);

    // Redirect based on Role
    if (isAdmin) {
        setCurrentRoute(AppRoute.ADMIN);
    } else {
        setCurrentRoute(AppRoute.DASHBOARD);
    }

    setIsAuthLoading(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('stemgolf_session');
    setIsAuthenticated(false);
    setCurrentRoute(AppRoute.LOGIN);
  };

  const handleNavigate = (route: AppRoute) => {
    if (!isAuthenticated && route !== AppRoute.LOGIN && route !== AppRoute.PUBLIC_PAGE) {
       setCurrentRoute(AppRoute.LOGIN);
       return;
    }
    // Simple RBAC check
    if (route === AppRoute.ADMIN && profile.role !== 'admin') {
        alert("Access Denied: Admins only.");
        return;
    }

    setCurrentRoute(route);
    PixelService.trackPageView(); // Track route changes as PageViews
    if (route !== AppRoute.STUDIO) {
      setEditingProject(null);
    }
  };

  const handleEditProject = (project: PodcastProject) => {
    setEditingProject(project);
    setCurrentRoute(AppRoute.STUDIO);
  };

  const handleSaveProject = async (project: PodcastProject) => {
    // Track Studio usage
    PixelService.trackStudioUsage(project.title, project.duration || 0);

    const saved = await db.projects.save(project);
    setProjects(prev => {
      const idx = prev.findIndex(p => p.id === saved.id);
      if (idx >= 0) {
        const newProjects = [...prev];
        newProjects[idx] = saved;
        return newProjects;
      }
      return [saved, ...prev];
    });

    // If currently editing, update that ref too
    if (editingProject?.id === saved.id) {
       setEditingProject(saved);
    }
  };

  const handleDeleteProject = async (id: string) => {
    if (confirm("Are you sure you want to delete this project?")) {
      await db.projects.delete(id);
      setProjects(prev => prev.filter(p => p.id !== id));
      if (editingProject?.id === id) {
        setEditingProject(null);
        setCurrentRoute(AppRoute.DASHBOARD);
      }
    }
  };

  const handleDuplicateProject = async (project: PodcastProject) => {
    const dup = { ...project, id: `proj_${Date.now()}`, title: `${project.title} (Copy)`, createdAt: Date.now() };
    await handleSaveProject(dup);
  };

  const handleUpdateProfile = async (newProfile: CreatorProfile) => {
    await db.users.saveProfile(newProfile);
    setProfile(newProfile);
    SEOService.updateTags(newProfile.seo);
    // Re-init pixel if ID changed
    if (newProfile.seo?.facebookPixelId) {
        PixelService.init(newProfile.seo.facebookPixelId);
    }
  };

  const handleSavePost = async (post: BlogPost) => {
    await db.content.save(post);
    setBlogPosts(prev => {
      const idx = prev.findIndex(p => p.id === post.id);
      if (idx >= 0) {
        const newPosts = [...prev];
        newPosts[idx] = post;
        return newPosts;
      }
      return [post, ...prev];
    });
  };

  const handleDeletePost = async (id: string) => {
     if (confirm("Delete this article?")) {
        await db.content.delete(id);
        setBlogPosts(prev => prev.filter(p => p.id !== id));
     }
  };

  const handleCreateSeries = async (series: Series) => {
    await db.series.save(series);
    setSeriesList(prev => [series, ...prev]);
  };

  if (isLoading) {
    return (
      <div className="h-screen w-full bg-[#020617] flex flex-col items-center justify-center text-white">
        <Loader2 className="w-10 h-10 animate-spin text-orange-600 mb-4" />
        <p className="text-slate-400 font-mono text-sm">Loading Studio...</p>
      </div>
    );
  }

  // Auth Gate
  if (!isAuthenticated && currentRoute !== AppRoute.PUBLIC_PAGE) {
     return <Login onLogin={handleLogin} isLoading={isAuthLoading} />;
  }

  return (
    <Layout currentRoute={currentRoute} onNavigate={handleNavigate} profile={profile} onLogout={handleLogout}>
      {currentRoute === AppRoute.DASHBOARD && (
        <Dashboard 
          onNavigate={handleNavigate} 
          onEditProject={handleEditProject} 
          projects={projects} 
        />
      )}

      {currentRoute === AppRoute.STUDIO && (
        <Studio 
          initialProject={editingProject}
          projects={projects}
          seriesList={seriesList} 
          creatorProfile={profile}
          onSave={handleSaveProject}
          onSelectProject={(p) => p ? handleEditProject(p) : handleNavigate(AppRoute.STUDIO)}
          onDeleteProject={handleDeleteProject}
          onDuplicateProject={handleDuplicateProject}
          onCreateBlogPost={handleSavePost}
          onCreateSeries={handleCreateSeries}
        />
      )}

      {currentRoute === AppRoute.BLOG_EDITOR && (
         <BlogEditor 
            posts={blogPosts}
            profile={profile}
            projects={projects}
            onSave={handleSavePost}
            onDelete={handleDeletePost}
         />
      )}

      {currentRoute === AppRoute.ANALYTICS && <Analytics />}

      {currentRoute === AppRoute.CREATOR_SETTINGS && (
        <CreatorSettings 
          profile={profile} 
          onUpdate={handleUpdateProfile} 
          onNavigate={handleNavigate}
        />
      )}

      {currentRoute === AppRoute.PUBLIC_PAGE && (
        <PublicPage 
          profile={profile} 
          projects={projects}
          posts={blogPosts}
          onNavigate={handleNavigate}
        />
      )}

      {currentRoute === AppRoute.STREAMING_DECK && (
          <StreamingDeck />
      )}

      {currentRoute === AppRoute.ADMIN && profile.role === 'admin' && (
          <AdminDashboard />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Mic, Music, Volume2, Radio, Play, Square, Activity, Bell, AlertTriangle, Info } from 'lucide-react';
import Button from '../components/Button';
import { generateJingle } from '../services/audioUtils';

// Types for the cart buttons
interface CartButton {
  id: string;
  label: string;
  color: string;
  type: 'news' | 'story' | 'upbeat';
  isPlaying: boolean;
}

const StreamingDeck: React.FC = () => {
  // --- CLOCK STATE ---
  const [time, setTime] = useState(new Date());

  // --- BROADCAST STATE ---
  const [isOnAir, setIsOnAir] = useState(false);
  const [isMicActive, setIsMicActive] = useState(false);

  // --- MIXER STATE ---
  const [volumes, setVolumes] = useState({
    mic: 1.0,
    sfx: 0.8,
    music: 0.6
  });

  // --- AUDIO REFS ---
  // We keep a dedicated audio context for the deck
  const audioCtxRef = useRef<AudioContext | null>(null);

  // --- CARTS STATE ---
  const [carts, setCarts] = useState<CartButton[]>([
    { id: '1', label: 'News Intro', color: 'bg-blue-600', type: 'news', isPlaying: false },
    { id: '2', label: 'Jingle 1', color: 'bg-green-600', type: 'upbeat', isPlaying: false },
    { id: '3', label: 'Drama Stab', color: 'bg-purple-600', type: 'story', isPlaying: false },
    { id: '4', label: 'Breaking', color: 'bg-red-600', type: 'news', isPlaying: false },
    { id: '5', label: 'Bed', color: 'bg-orange-600', type: 'story', isPlaying: false },
    { id: '6', label: 'Outro', color: 'bg-slate-600', type: 'upbeat', isPlaying: false },
  ]);

  // --- EFFECTS ---
  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    // Init Audio Context on mount
    audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    return () => {
        audioCtxRef.current?.close();
    };
  }, []);

  // --- HANDLERS ---

  const handleVolumeChange = (channel: keyof typeof volumes, val: number) => {
    setVolumes(prev => ({ ...prev, [channel]: val }));
  };

  const playCart = async (cartId: string) => {
    const cart = carts.find(c => c.id === cartId);
    if (!cart || !audioCtxRef.current) return;

    // Visual feedback
    setCarts(prev => prev.map(c => c.id === cartId ? { ...c, isPlaying: true } : c));

    try {
        // Generate Jingle Buffer
        const buffer = generateJingle(cart.type, audioCtxRef.current);

        const source = audioCtxRef.current.createBufferSource();
        source.buffer = buffer;

        const gain = audioCtxRef.current.createGain();
        gain.gain.value = volumes.sfx;

        source.connect(gain);
        gain.connect(audioCtxRef.current.destination);

        source.start();

        source.onended = () => {
            setCarts(prev => prev.map(c => c.id === cartId ? { ...c, isPlaying: false } : c));
        };
    } catch (e) {
        console.error("Audio error", e);
        setCarts(prev => prev.map(c => c.id === cartId ? { ...c, isPlaying: false } : c));
    }
  };

  // --- COMPONENTS ---

  // Vertical Fader Component
  const Fader = ({ label, icon: Icon, value, onChange, active = true }: { label: string, icon: any, value: number, onChange: (v: number) => void, active?: boolean }) => (
    <div className="flex flex-col items-center h-full bg-[#181818] p-4 rounded-xl border border-[#333] relative group">
       <div className={`p-2 rounded-full mb-4 transition-colors ${active ? 'bg-green-500/20 text-green-500' : 'bg-[#222] text-slate-500'}`}>
          <Icon className="w-6 h-6" />
       </div>

       <div className="flex-1 w-12 bg-[#121212] rounded-full relative flex justify-center py-2 border border-[#222]">
          {/* Track Fill */}
          <div 
            className={`absolute bottom-2 w-2 rounded-full transition-all ${active ? 'bg-orange-600' : 'bg-slate-700'}`}
            style={{ height: `calc(${value * 85}% + 10px)` }}
          ></div>

          {/* Input Range (Rotated) */}
          <input 
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={value}
            onChange={(e) => onChange(parseFloat(e.target.value))}
            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 -rotate-90 h-12 w-48 opacity-0 cursor-pointer z-10"
          />

          {/* Thumb Visual */}
          <div 
             className="absolute w-8 h-4 bg-white rounded shadow-lg border border-slate-300 pointer-events-none transition-all"
             style={{ bottom: `${value * 85}%` }}
          ></div>
       </div>

       <div className="mt-4 text-center">
          <div className="font-bold text-white text-sm">{Math.round(value * 100)}%</div>
          <div className="text-xs text-slate-500 uppercase tracking-wider font-bold mt-1">{label}</div>
       </div>
    </div>
  );

  return (
    <div className="h-full flex flex-col bg-[#0f0f0f] overflow-hidden">

        {/* Top Header / Clock Bar */}
        <div className="bg-[#121212] border-b border-[#272727] p-4 flex justify-between items-center shadow-lg z-10">
            <div className="flex items-center gap-4">
                <div className="flex flex-col">
                    <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Studio Time</span>
                    <span className="text-3xl font-mono font-bold text-white tracking-tight leading-none">
                        {time.toLocaleTimeString([], { hour12: false })}
                    </span>
                </div>
                <div className="h-8 w-px bg-[#333] mx-2"></div>
                <div className="flex items-center gap-2">
                    <div className={`w-3 h-3 rounded-full ${isOnAir ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
                    <span className={`text-sm font-bold uppercase tracking-wider ${isOnAir ? 'text-red-500' : 'text-slate-500'}`}>
                        {isOnAir ? 'LIVE ON AIR' : 'OFF AIR'}
                    </span>
                </div>
            </div>

            <div className="flex items-center gap-4">
                <Button 
                    onClick={() => setIsOnAir(!isOnAir)}
