                    <LogOut className="w-5 h-5" />
                    Sign Out
                  </button>
                )}
              </nav>
            </div>
          )}

          {/* Main Content Area */}
          <main className="flex-1 overflow-auto p-6 md:p-8 custom-scrollbar">
            {children}
          </main>
      </div>
    </div>
  );
};

export default Layout;

import React, { useState, useRef } from 'react';
import { Sponsor } from '../types';
import Button from '../components/Button';
import { Megaphone, Plus, Search, Tag, Globe, CheckCircle, XCircle, Upload, Trash2, Edit2, BadgeDollarSign, FileText } from 'lucide-react';

interface SponsorManagerProps {
  sponsors: Sponsor[];
  onSave: (sponsor: Sponsor) => void;
  onDelete: (id: string) => void;
}

const SponsorManager: React.FC<SponsorManagerProps> = ({ sponsors, onSave, onDelete }) => {
  const [view, setView] = useState<'list' | 'edit'>('list');
  const [searchTerm, setSearchTerm] = useState('');
  const [editingSponsor, setEditingSponsor] = useState<Partial<Sponsor>>({});

  // Refs for upload
  const logoInputRef = useRef<HTMLInputElement>(null);

  // Filter
  const filteredSponsors = sponsors.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.promoCode.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleEdit = (sponsor?: Sponsor) => {
    if (sponsor) {
        setEditingSponsor({ ...sponsor });
    } else {
        setEditingSponsor({
            id: `sponsor_${Date.now()}`,
            isActive: true,
            createdAt: Date.now()
        });
    }
    setView('edit');
  };

  const handleSave = () => {
    if (!editingSponsor.name || !editingSponsor.promoCode) {
        alert("Name and Promo Code are required.");
        return;
    }
    onSave(editingSponsor as Sponsor);
    setView('list');
    setEditingSponsor({});
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingSponsor(prev => ({ ...prev, logoUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleToggleActive = (sponsor: Sponsor) => {
      onSave({ ...sponsor, isActive: !sponsor.isActive });
  };

  if (view === 'edit') {
      return (
          <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in">
              <div className="flex justify-between items-center mb-6">
                  <h1 className="text-2xl font-bold text-white flex items-center gap-2">
                      <Megaphone className="w-6 h-6 text-orange-600" />
                      {editingSponsor.id && sponsors.find(s => s.id === editingSponsor.id) ? 'Edit Sponsor' : 'Add New Sponsor'}
                  </h1>
                  <div className="flex gap-2">
                      <Button variant="ghost" onClick={() => setView('list')}>Cancel</Button>
                      <Button onClick={handleSave}>Save Sponsor</Button>
                  </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  {/* Left: Logo & Basic Info */}
                  <div className="space-y-6">
                      <div className="bg-[#181818] p-6 rounded-xl border border-[#272727]">
                          <label className="block text-sm font-medium text-slate-400 mb-2">Sponsor Logo</label>
                          <div 
                            className="aspect-square bg-[#121212] rounded-lg border-2 border-dashed border-[#333] flex flex-col items-center justify-center cursor-pointer hover:border-orange-500 transition-colors relative overflow-hidden group"
                            onClick={() => logoInputRef.current?.click()}
                          >
                              {editingSponsor.logoUrl ? (
                                  <img src={editingSponsor.logoUrl} className="w-full h-full object-contain p-4" />
                              ) : (
                                  <div className="text-center p-4">
                                      <Upload className="w-8 h-8 text-slate-500 mx-auto mb-2" />
                                      <span className="text-xs text-slate-500">Click to upload</span>
                                  </div>
                              )}
                              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                  <span className="text-white text-xs font-bold">Change Logo</span>
                              </div>
                          </div>
                          <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
                      </div>

                      <div className="bg-[#181818] p-6 rounded-xl border border-[#272727] space-y-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-400 mb-1">Company Name *</label>
                              <input 
                                type="text" 
                                value={editingSponsor.name || ''} 
                                onChange={e => setEditingSponsor({...editingSponsor, name: e.target.value})}
                                className="w-full bg-[#121212] border border-[#333] rounded-lg px-3 py-2 text-white focus:border-orange-500"
                              />
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-slate-400 mb-1">Tagline</label>
                              <input 
                                type="text" 
                                value={editingSponsor.tagline || ''} 
                                onChange={e => setEditingSponsor({...editingSponsor, tagline: e.target.value})}
                                placeholder="e.g. The future of sound"
                                className="w-full bg-[#121212] border border-[#333] rounded-lg px-3 py-2 text-white focus:border-orange-500"
                              />
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-slate-400 mb-1">Website URL</label>
                              <div className="relative">
                                <Globe className="absolute left-3 top-2.5 w-4 h-4 text-slate-500" />
                                <input 
                                    type="text" 
                                    value={editingSponsor.websiteUrl || ''} 
                                    onChange={e => setEditingSponsor({...editingSponsor, websiteUrl: e.target.value})}
                                    placeholder="https://..."
                                    className="w-full bg-[#121212] border border-[#333] rounded-lg pl-9 pr-3 py-2 text-white focus:border-orange-500"
                                />
                              </div>
                          </div>
                      </div>
                  </div>

                  {/* Middle: Deal & Product Info */}
                  <div className="lg:col-span-2 space-y-6">
                      <div className="bg-[#181818] p-6 rounded-xl border border-[#272727]">
                          <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                              <BadgeDollarSign className="w-5 h-5 text-green-500" /> The Deal
                          </h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                              <div>
                                  <label className="block text-sm font-medium text-slate-400 mb-1">Promo Code *</label>
                                  <input 
                                    type="text" 
                                    value={editingSponsor.promoCode || ''} 
                                    onChange={e => setEditingSponsor({...editingSponsor, promoCode: e.target.value})}
                                    className="w-full bg-[#121212] border border-[#333] rounded-lg px-3 py-2 text-white font-mono font-bold tracking-wider focus:border-green-500"
                                  />
                              </div>
                              <div>
                                  <label className="block text-sm font-medium text-slate-400 mb-1">Offer Title</label>
                                  <input 
                                    type="text" 
                                    value={editingSponsor.offerTitle || ''} 
                                    onChange={e => setEditingSponsor({...editingSponsor, offerTitle: e.target.value})}
                                    placeholder="e.g. Get 20% Off Your First Order"
                                    className="w-full bg-[#121212] border border-[#333] rounded-lg px-3 py-2 text-white focus:border-green-500"
                                  />
                              </div>
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-slate-400 mb-1">Product / Service Description</label>
                              <textarea 
                                rows={4}
                                value={editingSponsor.description || ''}
                                onChange={e => setEditingSponsor({...editingSponsor, description: e.target.value})}
                                className="w-full bg-[#121212] border border-[#333] rounded-lg px-3 py-2 text-white focus:border-orange-500"
                                placeholder="Describe what they sell and why listeners should care..."
                              />
                          </div>
                      </div>

                      <div className="bg-[#181818] p-6 rounded-xl border border-[#272727]">
                          <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                              <FileText className="w-5 h-5 text-blue-500" /> Fine Print
                          </h3>
                          <div>
                              <label className="block text-sm font-medium text-slate-400 mb-1">Terms & Conditions</label>
                              <textarea 
                                rows={6}
                                value={editingSponsor.termsAndConditions || ''}
                                onChange={e => setEditingSponsor({...editingSponsor, termsAndConditions: e.target.value})}
                                className="w-full bg-[#121212] border border-[#333] rounded-lg px-3 py-2 text-slate-300 text-sm focus:border-orange-500 font-mono"
                                placeholder="- Valid for new customers only&#10;- Expires Dec 31, 2025&#10;- Cannot be combined with other offers"
                              />
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end border-b border-[#272727] pb-6">
        <div>
          <h1 className="text-3xl font-bold text-white mb-2">Program Sponsors</h1>
          <p className="text-slate-400">Manage active partnerships, promo codes, and terms for your listeners.</p>
        </div>
        <Button onClick={() => handleEdit()}>
          <Plus className="w-4 h-4 mr-2" /> Add Sponsor
        </Button>
      </div>

      <div className="flex items-center gap-4 mb-6">
          <div className="relative flex-1 max-w-md">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                <input 
                  type="text" 
                  placeholder="Search sponsors..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full bg-[#181818] border border-[#333] rounded-lg pl-9 pr-3 py-2 text-sm text-white focus:border-orange-500"
                />
          </div>
      </div>

      {filteredSponsors.length === 0 ? (
          <div className="text-center py-20 bg-[#181818] rounded-xl border border-[#272727] border-dashed">
              <Megaphone className="w-12 h-12 text-slate-600 mx-auto mb-4" />
              <h3 className="text-white font-medium">No sponsors yet</h3>
              <p className="text-slate-500 text-sm mt-1">Add your first program partner to start monetizing.</p>
          </div>
      ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredSponsors.map(sponsor => (
                  <div key={sponsor.id} className={`bg-[#181818] border rounded-xl overflow-hidden group transition-all ${sponsor.isActive ? 'border-[#333] hover:border-orange-500/50' : 'border-[#272727] opacity-60'}`}>
                      <div className="p-5 flex items-start justify-between">
                          <div className="flex items-center gap-4">
                              <div className="w-12 h-12 bg-white rounded-lg p-1 flex items-center justify-center overflow-hidden">
                                  {sponsor.logoUrl ? (
                                      <img src={sponsor.logoUrl} alt={sponsor.name} className="max-w-full max-h-full" />
                                  ) : (
                                      <Tag className="text-black w-6 h-6" />
                                  )}
                              </div>
                              <div>
                                  <h3 className="font-bold text-white text-lg">{sponsor.name}</h3>
                                  <div className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded-full inline-block ${sponsor.isActive ? 'bg-green-900/30 text-green-400' : 'bg-slate-800 text-slate-500'}`}>
                                      {sponsor.isActive ? 'Active' : 'Inactive'}
                                  </div>
                              </div>
                          </div>
                          <div className="flex gap-1">
                              <button onClick={() => handleEdit(sponsor)} className="p-2 text-slate-400 hover:text-white hover:bg-[#222] rounded-lg transition-colors">
                                  <Edit2 className="w-4 h-4" />
                              </button>
                              <button onClick={() => onDelete(sponsor.id)} className="p-2 text-slate-400 hover:text-red-400 hover:bg-red-900/20 rounded-lg transition-colors">
                                  <Trash2 className="w-4 h-4" />
                              </button>
                          </div>
                      </div>

                      <div className="px-5 pb-5">
                          <div className="bg-[#222] rounded-lg p-3 mb-4">
                              <div className="text-xs text-slate-500 uppercase font-bold mb-1">Current Offer</div>
                              <div className="text-white font-medium">{sponsor.offerTitle}</div>
                              <div className="mt-2 flex items-center justify-between bg-black/30 rounded px-2 py-1 border border-white/5">
                                  <code className="text-orange-500 font-mono font-bold">{sponsor.promoCode}</code>
                                  <span className="text-[10px] text-slate-600">PROMO CODE</span>
                              </div>
                          </div>

                          <div className="flex items-center justify-between border-t border-[#272727] pt-4">
                              <span className="text-xs text-slate-500 font-mono">Added: {new Date(sponsor.createdAt).toLocaleDateString()}</span>
                              <button 
                                onClick={() => handleToggleActive(sponsor)}
                                className={`text-xs font-bold flex items-center gap-1 ${sponsor.isActive ? 'text-red-400 hover:text-red-300' : 'text-green-400 hover:text-green-300'}`}
                              >
                                  {sponsor.isActive ? <XCircle className="w-3 h-3" /> : <CheckCircle className="w-3 h-3" />}
                                  {sponsor.isActive ? 'Deactivate' : 'Activate'}
                              </button>
                          </div>
                      </div>
                  </div>
              ))}
          </div>
      )}
    </div>
  );
};

export default SponsorManager;

import React, { useState, useEffect } from 'react';
import { CreatorProfile, PodcastProject, AppRoute, BlogPost, Sponsor } from '../types';
import { Play, Pause, ArrowLeft, Headphones, Mail, ArrowRight, Instagram, Twitter, Facebook, Linkedin, Circle, Calendar, User, Clock, Search, Home, Info, Mic, FileText, Phone, AlertTriangle, X, Menu, Share2, Volume2, SkipBack, SkipForward, Youtube, Link as LinkIcon, ExternalLink, Megaphone, Copy, Check, ChevronDown, ChevronUp } from 'lucide-react';

interface PublicPageProps {
  profile: CreatorProfile;
  projects: PodcastProject[];
  posts: BlogPost[];
  sponsors: Sponsor[];
  onNavigate: (route: AppRoute) => void;
}

type PublicView = 'home' | 'about' | 'episodes' | 'episode_detail' | 'blog' | 'blog_detail' | 'sponsors' | 'contact' | '404';

const PublicPage: React.FC<PublicPageProps> = ({ profile, projects, posts, sponsors, onNavigate }) => {
  const publishedEpisodes = projects.filter(p => p.distributionStatus === 'published' || p.distributionStatus === 'scheduled');
  const activeSponsors = sponsors.filter(s => s.isActive);

  // --- STATE ---
  const [currentView, setCurrentView] = useState<PublicView>('home');
  const [detailId, setDetailId] = useState<string | null>(null);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Filters
  const [episodeSearch, setEpisodeSearch] = useState('');
  const [blogCategory, setBlogCategory] = useState('All');

  // Audio Player State
  const [playingId, setPlayingId] = useState<string | null>(null);
  const [audioEl, setAudioEl] = useState<HTMLAudioElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);

  // --- THEME DERIVATION ---
  const accentColor = profile.brandColor || '#a855f7'; // Default to purple-500 hex
  const fontClass = profile.font === 'serif' ? 'font-serif' : 'font-sans';
  const theme = profile.theme || 'classic';

  // Base Background styles per theme
  const getThemeBackground = () => {
    switch (theme) {
      case 'minimal': return 'bg-[#080808]'; // Clean, flat dark
      case 'bold': return 'bg-[#020202]'; // Deep black, relies on gradients
      default: return 'bg-black bg-grid-pattern'; // Classic
    }
  };

  // --- AUDIO LOGIC ---
  useEffect(() => {
    if (audioEl) {
        const updateProgress = () => {
            if (audioEl.duration) {
                setProgress((audioEl.currentTime / audioEl.duration) * 100);
            }
        };
        const handleEnded = () => {
            setIsPlaying(false);
            setPlayingId(null);
            setProgress(0);
        };

        audioEl.addEventListener('timeupdate', updateProgress);
        audioEl.addEventListener('ended', handleEnded);

        return () => {
            audioEl.removeEventListener('timeupdate', updateProgress);
            audioEl.removeEventListener('ended', handleEnded);
        }
    }
  }, [audioEl]);

  const togglePlay = (project: PodcastProject, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (!project.audioUrl) return;

    if (playingId === project.id && audioEl) {
      if (!audioEl.paused) {
        audioEl.pause();
        setIsPlaying(false);
      } else {
        audioEl.play();
        setIsPlaying(true);
      }
    } else {
      if (audioEl) audioEl.pause();
      const newAudio = new Audio(project.audioUrl);
      newAudio.play();
      setIsPlaying(true);
      setAudioEl(newAudio);
      setPlayingId(project.id);
    }
  };

  const navigateTo = (view: PublicView, id: string | null = null) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setCurrentView(view);
    setDetailId(id);
    setMobileMenuOpen(false);
  };

  // --- SUB-COMPONENTS ---

  const StickyPlayer = () => {
    const episode = publishedEpisodes.find(p => p.id === playingId);
    if (!episode || !playingId) return null;

    return (
      <div className="fixed bottom-0 left-0 right-0 bg-[#0a0a0a]/95 border-t border-white/10 backdrop-blur-xl z-50 animate-in slide-in-from-bottom-full duration-300">
         <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between gap-4">
            {/* Track Info */}
            <div className="flex items-center gap-4 min-w-0 w-1/3">
               <div className="w-12 h-12 rounded bg-[#222] overflow-hidden flex-shrink-0 relative">
                 <img src={episode.metadata.coverArt || profile.coverImage} className="w-full h-full object-cover" />
                 <div className="absolute inset-0 bg-black/10"></div>
               </div>
               <div className="min-w-0 hidden sm:block">
                  <div className="text-sm font-bold text-white truncate">{episode.title}</div>
                  <div className="text-xs text-slate-400 truncate">{episode.metadata.author}</div>
               </div>
            </div>

            {/* Controls */}
            <div className="flex flex-col items-center flex-1 max-w-md">
               <div className="flex items-center gap-6 mb-1">
                  <button className="text-slate-400 hover:text-white transition-colors"><SkipBack className="w-5 h-5" /></button>
                  <button 
                    onClick={(e) => togglePlay(episode, e)}
                    className="w-10 h-10 bg-white rounded-full flex items-center justify-center text-black hover:scale-105 transition-transform"
                  >
                     {isPlaying ? <Pause className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-0.5" />}
                  </button>
                  <button className="text-slate-400 hover:text-white transition-colors"><SkipForward className="w-5 h-5" /></button>
               </div>
               {/* Progress Bar */}
               <div className="w-full flex items-center gap-2 text-[10px] text-slate-500 font-mono">
                  <span>{audioEl ? Math.floor(audioEl.currentTime / 60) : 0}:{audioEl ? Math.floor(audioEl.currentTime % 60).toString().padStart(2,'0') : '00'}</span>
                  <div className="flex-1 h-1 bg-[#333] rounded-full overflow-hidden cursor-pointer group">
                     <div className="h-full bg-[var(--accent)] rounded-full relative" style={{ width: `${progress}%` }}></div>
                  </div>
                  <span>{Math.floor((episode.duration || 0) / 60)}:{Math.floor((episode.duration || 0) % 60).toString().padStart(2,'0')}</span>
               </div>
            </div>

            {/* Volume / Extra */}
            <div className="w-1/3 flex justify-end items-center gap-4">
               <button className="text-slate-400 hover:text-white hidden sm:block"><Volume2 className="w-5 h-5" /></button>
               <button className="text-slate-400 hover:text-white hidden sm:block"><Share2 className="w-5 h-5" /></button>
            </div>
         </div>
      </div>
    );
  };

  const Navbar = () => (
    <nav className="w-full max-w-7xl mx-auto p-6 flex justify-between items-center relative z-40">
       <div 
         className="text-2xl font-bold tracking-tighter cursor-pointer flex items-center gap-1 hover:opacity-80 transition-opacity" 
         onClick={() => navigateTo('home')}
       >
         {profile.name}<span className="text-[var(--accent)] text-4xl leading-3">.</span>
       </div>

       {/* Desktop Nav */}
       <div className="hidden md:flex gap-8 text-sm font-medium text-slate-400">
          {[
             { id: 'home', label: 'Home' },
             { id: 'about', label: 'About' },
             { id: 'episodes', label: 'Episodes' },
             { id: 'blog', label: 'Blog' },
             { id: 'sponsors', label: 'Sponsors' },
             { id: 'contact', label: 'Contact' }
          ].map(link => (
             <button 
               key={link.id}
               onClick={() => navigateTo(link.id as PublicView)} 
               className={`hover:text-white transition-colors relative py-1 ${currentView.includes(link.id) || (link.id === 'home' && currentView === 'home') ? 'text-white after:absolute after:bottom-0 after:left-0 after:w-full after:h-px after:bg-[var(--accent)]' : ''}`}
             >
               {link.label}
             </button>
          ))}
       </div>

       <div className="hidden md:block">
         <button className="px-6 py-2.5 bg-white text-black font-bold rounded-full text-sm hover:bg-slate-200 transition-all">
           Subscribe
         </button>
       </div>

       {/* Mobile Toggle */}
       <button className="md:hidden text-white p-2" onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
          {mobileMenuOpen ? <X /> : <Menu />}
       </button>

       {/* Mobile Menu */}
       {mobileMenuOpen && (
         <div className="absolute top-full left-0 right-0 bg-[#0f0f0f] border-b border-white/10 p-4 flex flex-col gap-4 md:hidden shadow-2xl animate-in slide-in-from-top-2">
            {[
             { id: 'home', label: 'Home' },
             { id: 'about', label: 'About' },
             { id: 'episodes', label: 'Episodes' },
             { id: 'blog', label: 'Blog' },
             { id: 'sponsors', label: 'Sponsors' },
             { id: 'contact', label: 'Contact' }
            ].map(link => (
              <button 
                key={link.id}
                onClick={() => navigateTo(link.id as PublicView)}
                className={`text-left px-4 py-3 rounded-lg text-lg font-medium ${currentView.includes(link.id) ? 'bg-white/10 text-white' : 'text-slate-400'}`}
              >
                {link.label}
              </button>
            ))}
             <button className="w-full py-3 bg-[var(--accent)] text-white font-bold rounded-lg mt-2">
               Subscribe
             </button>
         </div>
       )}
    </nav>
  );

  const Footer = () => (
    <section className="py-24 border-t border-white/10 mt-auto bg-black/50 backdrop-blur-sm">
      <div className="max-w-7xl mx-auto px-6">
         <div className="grid grid-cols-1 md:grid-cols-4 gap-12 text-left">
            <div className="md:col-span-1">
               <h3 className="font-bold text-2xl mb-6 text-white">{profile.name}<span className="text-[var(--accent)]">.</span></h3>
               <p className="text-sm text-slate-500 leading-relaxed mb-6">
                  Unlocking stories, sparking conversations, and inspiring change through AI-powered audio content.
               </p>
               <div className="flex flex-wrap gap-4">
                  {profile.links.youtube && (
                      <a href={profile.links.youtube} target="_blank" rel="noopener noreferrer" className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-white/10 transition-all"><Youtube className="w-5 h-5" /></a>
